//! Two legitimate control strategies. Both only ever read `bars[..=i-1]`
//! when computing `feature[i]`, and both use `execution_offset() == 1`
//! (the honest default) -- the causal contract the leaky strategies in
//! `leaky.rs` each violate in a different way.

use crate::engine::{Bar, Strategy};

/// Bets against the previous bar's already-realized return, sized by the
/// magnitude of that return. The synthetic price generator (`engine::price`)
/// bakes in a small negative AR(1) coefficient on returns, so this captures
/// a real, modest, legitimate edge -- it is not a strawman with zero
/// expected edge.
pub struct HonestMeanReversion;

impl Strategy for HonestMeanReversion {
    fn name(&self) -> &str {
        "honest_mean_reversion"
    }

    fn compute_features(&self, bars: &[Bar]) -> Vec<f64> {
        let mut feature = vec![0.0; bars.len()];
        for i in 1..bars.len() {
            let prev_ret = (bars[i].close - bars[i - 1].close) / bars[i - 1].close;
            feature[i] = -prev_ret * 5.0;
        }
        feature
    }
}

/// The honest version of `leaky::ForwardWindowLookahead`/
/// `leaky::ExecutionTimingMismatch`: same trailing-mean-deviation idea, but
/// the window ends at `i - 1` (properly lagged, as if `.shift(1)` had been
/// applied) rather than at `i`.
pub struct HonestTrailingWindow {
    pub window: usize,
}

impl Strategy for HonestTrailingWindow {
    fn name(&self) -> &str {
        "honest_trailing_window"
    }

    fn compute_features(&self, bars: &[Bar]) -> Vec<f64> {
        let closes: Vec<f64> = bars.iter().map(|b| b.close).collect();
        let mut feature = vec![0.0; bars.len()];
        for i in 1..closes.len() {
            let end = i - 1;
            let start = end.saturating_sub(self.window - 1);
            let slice = &closes[start..=end];
            let mean = slice.iter().sum::<f64>() / slice.len() as f64;
            feature[i] = (mean - closes[end]) / closes[end];
        }
        feature
    }
}

