//! Three seeded leakage bugs, one per `problem.md` category.
//!
//! All three are deliberately built as *persistent* leaks -- the
//! contaminating information isn't confined to exactly one bar -- because an
//! exactly-one-bar-radius leak is, by construction, undone by a one-bar shift
//! test just as thoroughly as a genuine signal is (shifting a `t -> t+1`
//! peek by one bar turns it into a `t-1 -> t` peek, which is honest). See
//! `verify::shift_test` and `CHANGELOG.md` for the empirical evidence this
//! design choice is based on, and the exception (`ExecutionTimingMismatch`
//! below) that the shift-test alone cannot catch.

use crate::engine::{Bar, Strategy};

fn trailing_mean(closes: &[f64], end_inclusive: usize, window: usize) -> f64 {
    let start = end_inclusive.saturating_sub(window - 1);
    let slice = &closes[start..=end_inclusive];
    slice.iter().sum::<f64>() / slice.len() as f64
}

/// **Category 1 -- off-by-one in a rolling window.** The window is meant to
/// be trailing (`close[i-K+1..=i]`, shifted back one bar before use) but was
/// coded as a forward/centered window that includes bar `i` and the next
/// `K-1` bars. Because the window is `K` bars wide, a one-bar shift only
/// removes 1 of `K` future bars from the contamination -- the leak survives.
pub struct ForwardWindowLookahead {
    pub window: usize,
}

impl Strategy for ForwardWindowLookahead {
    fn name(&self) -> &str {
        "forward_window_lookahead"
    }

    fn compute_features(&self, bars: &[Bar]) -> Vec<f64> {
        let closes: Vec<f64> = bars.iter().map(|b| b.close).collect();
        let n = closes.len();
        (0..n)
            .map(|i| {
                let end = (i + self.window - 1).min(n - 1);
                let slice = &closes[i..=end];
                let forward_mean = slice.iter().sum::<f64>() / slice.len() as f64;
                // Signal: bet that price will move toward the forward-window
                // mean -- except that mean is built from bars the strategy
                // could not have seen yet.
                (forward_mean - closes[i]) / closes[i]
            })
            .collect()
    }
}

/// **Category 3 -- improper chronological split.** The feature is a z-score,
/// but `mean`/`std` are fit once over the *entire* series (including bars far
/// in the future of whatever index is being scored) instead of an expanding
/// or trailing window computed only from bars available up to that index.
/// This is the classic "standardize before splitting" bug. The contaminating
/// constant is identical at every index, so it is maximally shift-invariant:
/// shifting by any number of bars changes nothing about the leak.
pub struct GlobalNormalizationLeak;

impl Strategy for GlobalNormalizationLeak {
    fn name(&self) -> &str {
        "global_normalization_leak"
    }

    fn compute_features(&self, bars: &[Bar]) -> Vec<f64> {
        let closes: Vec<f64> = bars.iter().map(|b| b.close).collect();
        let n = closes.len() as f64;
        let global_mean = closes.iter().sum::<f64>() / n;
        let global_var = closes.iter().map(|c| (c - global_mean).powi(2)).sum::<f64>() / n;
        let global_std = global_var.sqrt().max(1e-9);

        closes
            .iter()
            .map(|&c| {
                let z = (c - global_mean) / global_std;
                // Mean-revert toward the *whole-series* mean -- only knowable
                // in hindsight, once every bar (including future ones) exists.
                -z * 0.1
            })
            .collect()
    }
}

/// **Category 2 -- execution timing mismatch.** The feature itself is an
/// honest, causal trailing-window signal (uses only `bars[..=i]`, which is
/// legitimate for "the reading as of now"). The bug is in
/// `execution_offset`: it bets on the return realized *over the same bar*
/// the feature was computed from, instead of the next bar. Because the
/// feature legitimately depends on `close[i]` and the return it's paired
/// with is also a direct function of `close[i]`, this is a real look-ahead
/// leak -- but a one-bar *feature* shift alone actually cures it (it turns
/// the pairing back into the honest `feature[i-1]` vs `return over bar i`
/// contract), so the shift-test's delta looks deceptively like a clean
/// collapse. We catch this one via the implausible-Sharpe ceiling instead;
/// see `verify::audit`.
pub struct ExecutionTimingMismatch {
    pub window: usize,
}

impl Strategy for ExecutionTimingMismatch {
    fn name(&self) -> &str {
        "execution_timing_mismatch"
    }

    fn compute_features(&self, bars: &[Bar]) -> Vec<f64> {
        let closes: Vec<f64> = bars.iter().map(|b| b.close).collect();
        (0..closes.len())
            .map(|i| {
                let mean = trailing_mean(&closes, i, self.window);
                (closes[i] - mean) / mean
            })
            .collect()
    }

    fn execution_offset(&self) -> usize {
        0
    }
}

