    /// `.env` support -- see `.env.example`.
    pub fn from_env() -> Result<Self> {
        let api_key = std::env::var("ANTHROPIC_API_KEY").context(
            "ANTHROPIC_API_KEY is not set. Copy .env.example to .env and fill in a real key.",
        )?;
        let model = std::env::var("ANTHROPIC_MODEL").unwrap_or_else(|_| DEFAULT_MODEL.to_string());
        Ok(Client {
            api_key,
            model,
            http: reqwest::blocking::Client::new(),
        })
    }

    pub fn send(&self, system: &str, messages: &[Message], tools: &[ToolDef]) -> Result<ApiResponse> {
        let mut body = json!({
            "model": self.model,
            "max_tokens": MAX_TOKENS,
            "system": system,
            "messages": messages.iter().map(message_to_json).collect::<Vec<_>>(),
        });
        if !tools.is_empty() {
            body["tools"] = Value::Array(tools.iter().map(tool_to_json).collect());
        }

        let resp = self
            .http
            .post(API_URL)
            .header("Content-Type", "application/json")
            .header("x-api-key", &self.api_key)
            .header("anthropic-version", ANTHROPIC_VERSION)
            .json(&body)
            .send()
            .context("sending request to the Anthropic API")?;

        let status = resp.status();
        let raw: Value = resp
            .json()
            .context("parsing the Anthropic API response body")?;
        if !status.is_success() {
            bail!("Anthropic API returned {status}: {raw}");
        }
        parse_response(&raw)
    }
}

fn tool_to_json(tool: &ToolDef) -> Value {
    json!({
        "name": tool.name,
        "description": tool.description,
        "input_schema": tool.input_schema,
    })
}

fn message_to_json(message: &Message) -> Value {
    json!({
        "role": message.role,
        "content": message.content.iter().map(content_block_to_json).collect::<Vec<_>>(),
    })
}

fn content_block_to_json(block: &ContentBlock) -> Value {
    match block {
        ContentBlock::Text { text } => json!({"type": "text", "text": text}),
        ContentBlock::ToolUse { id, name, input } => {
            json!({"type": "tool_use", "id": id, "name": name, "input": input})
        }
        ContentBlock::ToolResult {
            tool_use_id,
            content,
        } => json!({"type": "tool_result", "tool_use_id": tool_use_id, "content": content}),
    }
}

fn parse_response(raw: &Value) -> Result<ApiResponse> {
    let content_arr = raw
        .get("content")
        .and_then(|c| c.as_array())
        .context("response missing `content` array")?;

    let mut content = Vec::with_capacity(content_arr.len());
    for block in content_arr {
        let block_type = block.get("type").and_then(|t| t.as_str()).unwrap_or("");
        match block_type {
            "text" => content.push(ContentBlock::Text {
                text: block
                    .get("text")
                    .and_then(|t| t.as_str())
                    .unwrap_or_default()
                    .to_string(),
            }),
            "tool_use" => content.push(ContentBlock::ToolUse {
                id: block.get("id").and_then(|v| v.as_str()).unwrap_or_default().to_string(),
                name: block
                    .get("name")
                    .and_then(|v| v.as_str())
                    .unwrap_or_default()
                    .to_string(),
                input: block.get("input").cloned().unwrap_or(Value::Null),
            }),
            // "thinking" and other block types are intentionally ignored --
            // the trajectory log captures our own reasoning steps, not the
            // model's internal chain of thought.
            _ => {}
        }
    }

    let stop_reason = raw
        .get("stop_reason")
        .and_then(|s| s.as_str())
        .unwrap_or("unknown")
        .to_string();
    let input_tokens = raw
        .get("usage")
        .and_then(|u| u.get("input_tokens"))
        .and_then(|v| v.as_u64())
        .unwrap_or(0) as u32;
    let output_tokens = raw
        .get("usage")
        .and_then(|u| u.get("output_tokens"))
        .and_then(|v| v.as_u64())
        .unwrap_or(0) as u32;

    Ok(ApiResponse {
        content,
        stop_reason,
        input_tokens,
        output_tokens,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_a_text_response() {
        let raw = json!({
            "content": [{"type": "text", "text": "hello"}],
            "stop_reason": "end_turn",
            "usage": {"input_tokens": 10, "output_tokens": 5}
        });
        let resp = parse_response(&raw).unwrap();
        assert_eq!(resp.text(), "hello");
        assert_eq!(resp.stop_reason, "end_turn");
        assert_eq!(resp.input_tokens, 10);
        assert_eq!(resp.output_tokens, 5);
    }

    #[test]
    fn parses_a_tool_use_response() {
        let raw = json!({
            "content": [
                {"type": "text", "text": "Let me check."},
                {"type": "tool_use", "id": "toolu_1", "name": "shift_test", "input": {"strategy": "foo"}}
            ],
            "stop_reason": "tool_use",
            "usage": {"input_tokens": 20, "output_tokens": 8}
        });
        let resp = parse_response(&raw).unwrap();
        let uses = resp.tool_uses();
        assert_eq!(uses.len(), 1);
        assert_eq!(uses[0].0, "toolu_1");
        assert_eq!(uses[0].1, "shift_test");
    }
}

