//! The real agent: reasoning -> hypothesis -> tool call (`shift_test`) ->
//! empirical verification -> verdict, with a targeted retry when the
//! model's read of the evidence disagrees with the empirically-justified
//! two-signal rule (`verify::audit`) -- see `problem.md` §03 step 4 ("If
//! inconclusive, it explores an alternative hypothesis").

use anyhow::{Context, Result};
use clap::Parser;
use frontier_challenge::engine::{generate_series, PriceParams};
use frontier_challenge::llm::{Client, ContentBlock, Message, ToolDef};
use frontier_challenge::strategies::find_by_name;
use frontier_challenge::telemetry::Trajectory;
use frontier_challenge::verify::{audit, shift_test, ShiftTestResult, Verdict};
use serde_json::json;
use std::path::PathBuf;

#[derive(Parser)]
struct Args {
    /// Path to a strategy source file, e.g.
    /// src/strategies/forward_window_lookahead.rs
    strategy_file: PathBuf,
}

const SYSTEM_PROMPT: &str = "You are auditing a quantitative trading strategy's Rust source code for data leakage and look-ahead bias -- e.g. features computed from future bars, execution against a return that already happened, or normalization/statistics fit on the whole series instead of only past data. \
Do not trust your own read of the code alone: you have one empirical tool, shift_test, which reruns the real backtest with the strategy's computed features shifted forward by exactly one bar and reports the Sharpe ratio before and after. \
An honest strategy's edge is fragile: shifting it degrades performance toward noise. A leaky strategy is often robust to the shift because the contaminating information isn't confined to one bar. But also weigh the ORIGINAL Sharpe on its own merits: this synthetic market has roughly 1% daily volatility and only a small genuine mean-reversion edge, so a Sharpe ratio far beyond what any real signal could sustain here is itself suspicious, even in a case where the shift happens to degrade it a lot. \
Form a hypothesis, call shift_test to check it, then state your verdict as exactly one word on the first line of your final answer: LEAKY or CLEAN, followed by a short justification referencing the actual numbers returned.";

fn shift_test_tool() -> ToolDef {
    ToolDef {
        name: "shift_test".to_string(),
        description: "Reruns the strategy's real backtest against the same deterministic synthetic price series twice: once as coded, once with its computed feature series shifted forward by exactly one bar (a stand-in for 'what if this had to rely on slightly older information'). Returns sharpe_original, sharpe_shifted, and their delta. Takes no strategy identifier -- it always tests the strategy currently under audit.".to_string(),
        input_schema: json!({
            "type": "object",
            "properties": {
                "hypothesis": {
                    "type": "string",
                    "description": "The specific look-ahead mechanism you suspect in the source, stated before running the test."
                }
            },
            "required": ["hypothesis"]
        }),
    }
}

fn parse_verdict(text: &str) -> Option<Verdict> {
    let first_word = text.lines().next()?.trim().trim_end_matches('.').to_uppercase();
    if first_word.starts_with("LEAKY") {
        Some(Verdict::Leaky)
    } else if first_word.starts_with("CLEAN") {
        Some(Verdict::Clean)
    } else {
        None
    }
}

fn main() -> Result<()> {
    dotenvy::dotenv().ok();
    let args = Args::parse();

    let source = std::fs::read_to_string(&args.strategy_file)
        .with_context(|| format!("reading {}", args.strategy_file.display()))?;
    let strategy_name = args
        .strategy_file
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("unknown_strategy")
        .to_string();
    let entry = find_by_name(&strategy_name).with_context(|| {
        format!(
            "'{strategy_name}' is not a registered seeded strategy (see strategies::all_strategies); \
             the advanced agent can only empirically verify strategies the harness knows how to rerun."
        )
    })?;

    let mut trajectory = Trajectory::new("advanced", &strategy_name);
    let client = Client::from_env()?;
    let bars = generate_series(PriceParams::default());
    let tool = shift_test_tool();

    let user_prompt = format!(
        "Strategy source ({}):\n\n```rust\n{}\n```\n\nInspect this for look-ahead bias or data leakage. State your initial hypothesis, then call shift_test to empirically verify it before concluding.",
        args.strategy_file.display(),
        source
    );
    trajectory.record_reasoning(format!(
        "Read {} ({} bytes); one empirical tool (shift_test) is available.",
        args.strategy_file.display(),
        source.len()
    ));

    let mut messages = vec![Message::user_text(&user_prompt)];
    let mut empirical_result: Option<ShiftTestResult> = None;

    // Round 1: give the model the source and let it decide whether to call
    // the tool. Bounded to 2 attempts total (initial + one forced nudge) --
    // an agent that refuses to use its only verification tool is a failure
    // mode we surface, not paper over.
    let mut response = client.send(SYSTEM_PROMPT, &messages, std::slice::from_ref(&tool))?;
    trajectory.add_tokens(response.input_tokens, response.output_tokens);

    for attempt in 0..2 {
        let pre_tool_text = response.text();
        if !pre_tool_text.trim().is_empty() {
            trajectory.record_reasoning(pre_tool_text);
        }

        let first_call = response
            .tool_uses()
            .first()
            .map(|(id, name, input)| (id.to_string(), name.to_string(), (*input).clone()));

        messages.push(Message {
            role: "assistant",
            content: response.content,
        });

        match first_call {
            Some((tool_id, _name, input)) => {
                let hypothesis = input
                    .get("hypothesis")
                    .and_then(|v| v.as_str())
                    .unwrap_or("(no hypothesis stated)")
                    .to_string();
                trajectory.record_tool_call(
                    "shift_test",
                    json!({"strategy": strategy_name, "hypothesis": hypothesis}),
                );

                let result = shift_test(&bars, entry.strategy.as_ref());
                trajectory.record_tool_output(json!({
                    "sharpe_original": result.sharpe_original,
                    "sharpe_shifted": result.sharpe_shifted,
                    "delta": result.delta,
                }));
                empirical_result = Some(result);

                let tool_result_text = format!(
                    "sharpe_original={:.3} sharpe_shifted={:.3} delta={:.3}",
                    result.sharpe_original, result.sharpe_shifted, result.delta
                );
                messages.push(Message {
                    role: "user",
                    content: vec![ContentBlock::ToolResult {
                        tool_use_id: tool_id,
                        content: tool_result_text,
                    }],
                });
                response = client.send(SYSTEM_PROMPT, &messages, std::slice::from_ref(&tool))?;
                trajectory.add_tokens(response.input_tokens, response.output_tokens);
                break;
            }
            None if attempt == 0 => {
                trajectory.record_reasoning(
                    "Model did not call shift_test on the first turn; nudging it to use the tool before concluding."
                        .to_string(),
                );
                messages.push(Message::user_text(
                    "You have not verified your hypothesis yet. Call shift_test now -- an unverified read is not an audit.",
                ));
                response = client.send(SYSTEM_PROMPT, &messages, std::slice::from_ref(&tool))?;
                trajectory.add_tokens(response.input_tokens, response.output_tokens);
            }
            None => {
                trajectory.record_reasoning(
                    "Model still did not call shift_test after a nudge. Falling back: the harness runs shift_test itself so the reported verdict is still empirically grounded, and this failure mode is surfaced rather than hidden."
                        .to_string(),
                );
                empirical_result = Some(shift_test(&bars, entry.strategy.as_ref()));
                break;
            }
        }
    }

    let empirical_result = empirical_result.context("no shift-test result available")?;
    let empirical_verdict = audit(&empirical_result);
    trajectory.record_verification(format!(
        "shift_test: sharpe_original={:.3} sharpe_shifted={:.3} delta={:.3} -> two-signal rule says {:?}",
        empirical_result.sharpe_original,
        empirical_result.sharpe_shifted,
        empirical_result.delta,
        empirical_verdict
    ));

    let mut final_text = response.text();
    let mut model_verdict = parse_verdict(&final_text);

    // Self-correction: if the model's read disagrees with the empirically
    // justified rule, give it one more targeted look before finalizing.
    if model_verdict != Some(empirical_verdict) {
        trajectory.record_reasoning(format!(
            "Model's verdict ({model_verdict:?}) disagrees with the empirical two-signal rule ({empirical_verdict:?}). Offering one alternative-hypothesis pass."
        ));
        messages.push(Message {
            role: "assistant",
            content: vec![ContentBlock::Text {
                text: final_text.clone(),
            }],
        });
        messages.push(Message::user_text(
            "Reconsider: don't judge robustness by the delta alone. Is sharpe_original, taken on its own, plausible for a legitimate signal on ~1% daily volatility synthetic data with only a small real mean-reversion edge -- even in a case where the shift happened to degrade it substantially? State your final verdict as the first line: LEAKY or CLEAN.",
        ));
        let retry = client.send(SYSTEM_PROMPT, &messages, std::slice::from_ref(&tool))?;
        trajectory.add_tokens(retry.input_tokens, retry.output_tokens);
        final_text = retry.text();
        model_verdict = parse_verdict(&final_text);
        trajectory.record_verification(format!("alternate-hypothesis pass -> {model_verdict:?}"));
    }

    let reported_verdict = model_verdict.unwrap_or(empirical_verdict);
    trajectory.record_final_verdict(
        format!("{reported_verdict:?}").to_uppercase(),
        empirical_result.delta,
        if model_verdict == Some(empirical_verdict) {
            "model agrees with empirical rule"
        } else if model_verdict.is_none() {
            "model gave no parseable verdict; fell back to empirical rule"
        } else {
            "model disagrees with empirical rule after retry; reporting model's stated verdict"
        },
    );

    println!("strategy: {strategy_name}");
    println!(
        "shift-test: sharpe_original={:.3} sharpe_shifted={:.3} delta={:.3}",
        empirical_result.sharpe_original, empirical_result.sharpe_shifted, empirical_result.delta
    );
    println!("empirical rule verdict: {empirical_verdict:?}");
    println!("agent verdict:          {reported_verdict:?}");
    println!("\n--- model's final answer ---\n{final_text}");

    let trajectory_dir = PathBuf::from("trajectories");
    let path = trajectory.finish_and_write(&trajectory_dir)?;
    eprintln!("\ntrajectory written to {}", path.display());

    Ok(())
}

