1	//! Minimal backtest loop: a strategy's per-bar feature values in, per-bar
2	//! returns and a Sharpe ratio out.
3	//!
4	//! The engine does not impose a single fixed decision-to-execution lag.
5	//! Instead each `Strategy` declares its own `execution_offset` -- how many
6	//! bars separate the feature it computed from the return it is applied to.
7	//! `1` is the honest convention (decide using information through bar `i`,
8	//! earn the return realized over bar `i+1`). `0` is the "execution timing
9	//! mismatch" bug from `problem.md` (bet on the very return whose bar the
10	//! feature was computed from). Keeping this as a per-strategy declaration
11	//! rather than a hard-coded engine constant is what lets one seeded strategy
12	//! carry that specific bug without special-casing the engine.
13	
14	use super::price::Bar;
15	
16	pub trait Strategy {
17	    fn name(&self) -> &str;
18	
19	    /// Returns one feature value per bar. Implementations are free (and, for
20	    /// the seeded leaky strategies, deliberately wrong) about which bars they
21	    /// read to compute `feature[i]` -- that is where look-ahead bias lives.
22	    fn compute_features(&self, bars: &[Bar]) -> Vec<f64>;
23	
24	    /// Bars between the feature index and the return it is applied to.
25	    /// `1` = correct ("trade at the next bar"). `0` = the execution-timing bug.
26	    fn execution_offset(&self) -> usize {
27	        1
28	    }
29	}
30	
31	#[derive(Debug, Clone)]
32	pub struct BacktestResult {
33	    pub returns: Vec<f64>,
34	    pub sharpe: f64,
35	    pub mean_return: f64,
36	    pub std_return: f64,
37	}
38	
39	/// Per-bar percentage return, close-to-close. `returns[i]` is the return
40	/// realized over bar `i` (from `close[i-1]` to `close[i]`); index 0 is
41	/// undefined and omitted, so `returns.len() == bars.len() - 1`.
42	pub fn close_to_close_returns(bars: &[Bar]) -> Vec<f64> {
43	    bars.windows(2)
44	        .map(|w| (w[1].close - w[0].close) / w[0].close)
45	        .collect()
46	}
47	
48	/// Runs `strategy` against `bars` using its declared execution offset and
49	/// returns the realized PnL series and Sharpe ratio.
50	///
51	/// Position sizing: `feature[i]` is clamped to `[-1, 1]` and used directly as
52	/// exposure -- no leverage, no compounding, so the Sharpe ratio reflects pure
53	/// signal quality rather than money-management choices.
54	pub fn run_backtest(bars: &[Bar], strategy: &dyn Strategy) -> BacktestResult {
55	    let feature = strategy.compute_features(bars);
56	    assert_eq!(
57	        feature.len(),
58	        bars.len(),
59	        "{} must return one feature value per bar",
60	        strategy.name()
61	    );
62	    run_backtest_from_features(bars, &feature, strategy.execution_offset())
63	}
64	
65	/// Same PnL/Sharpe computation as [`run_backtest`], but takes an already
66	/// -computed feature vector directly. This is what lets `verify::shift_test`
67	/// rerun a strategy against a *perturbed* feature series without needing a
68	/// second `Strategy` impl per strategy under test.
69	pub fn run_backtest_from_features(bars: &[Bar], feature: &[f64], offset: usize) -> BacktestResult {
70	    let rets = close_to_close_returns(bars);
71	
72	    // Bar 0 has no realized return regardless of offset, so iteration always
73	    // starts at 1; `offset` only changes which feature index pairs with it
74	    // (offset=1: feature[i-1], the honest "decide before, earn after"
75	    // contract; offset=0: feature[i], the execution-timing bug that pairs a
76	    // feature with the very bar's return it was computed from).
77	    let start = offset.max(1);
78	    let mut pnl = Vec::with_capacity(bars.len().saturating_sub(start));
79	    for i in start..bars.len() {
80	        let position = feature[i - offset].clamp(-1.0, 1.0);
81	        let ret = rets[i - 1];
82	        pnl.push(position * ret);
83	    }
84	
85	    sharpe_from_returns(pnl)
86	}
87	
88	fn sharpe_from_returns(returns: Vec<f64>) -> BacktestResult {
89	    let n = returns.len() as f64;
90	    if returns.is_empty() {
91	        return BacktestResult {
92	            returns,
93	            sharpe: 0.0,
94	            mean_return: 0.0,
95	            std_return: 0.0,
96	        };
97	    }
98	    let mean = returns.iter().sum::<f64>() / n;
99	    let variance = returns.iter().map(|r| (r - mean).powi(2)).sum::<f64>() / n;
100	    let std = variance.sqrt();
101	    // Annualize assuming daily-ish bars (252 periods/year), the standard convention.
102	    let sharpe = if std > 1e-12 {
103	        (mean / std) * (252.0_f64).sqrt()
104	    } else {
105	        0.0
106	    };
107	    BacktestResult {
108	        returns,
109	        sharpe,
110	        mean_return: mean,
111	        std_return: std,
112	    }
113	}
