        }
    }

    fn send_anthropic(
        &self,
        system: &str,
        messages: &[Message],
        tools: &[ToolDef],
    ) -> Result<ApiResponse> {
        let mut body = json!({
            "model": self.model,
            "max_tokens": MAX_TOKENS,
            "system": system,
            "messages": messages.iter().map(anthropic_message_to_json).collect::<Vec<_>>(),
