            .http
            .post(ANTHROPIC_API_URL)
            .header("Content-Type", "application/json")
            .header("x-api-key", &self.api_key)
            .header("anthropic-version", ANTHROPIC_VERSION)
            .json(&body)
            .send()
            .context("sending request to the Anthropic API")?;

        let raw = read_json_body(resp, "Anthropic")?;
        parse_anthropic_response(&raw)
    }

    fn send_gemini(
        &self,
        system: &str,
        messages: &[Message],
        tools: &[ToolDef],
    ) -> Result<ApiResponse> {
        let mut body = json!({
            "contents": messages_to_gemini_contents(messages),
            "systemInstruction": {"parts": [{"text": system}]},
        });
        if !tools.is_empty() {
            body["tools"] = json!([{
                "functionDeclarations": tools.iter().map(gemini_function_declaration).collect::<Vec<_>>(),
            }]);
