            .http
            .post(&url)
            .header("Content-Type", "application/json")
            .json(&body)
            .send()
            .context("sending request to the Gemini API")?;

        let raw = read_json_body(resp, "Gemini")?;
        parse_gemini_response(&raw)
    }
}

