fn parse_gemini_response(raw: &Value) -> Result<ApiResponse> {
    let candidate = raw
        .get("candidates")
        .and_then(|c| c.as_array())
        .and_then(|arr| arr.first())
        .context("response missing `candidates[0]`")?;

    let parts = candidate
        .get("content")
        .and_then(|c| c.get("parts"))
        .and_then(|p| p.as_array())
        .cloned()
        .unwrap_or_default();

    let mut content = Vec::with_capacity(parts.len());
    for part in &parts {
        if let Some(text) = part.get("text").and_then(|t| t.as_str()) {
            content.push(ContentBlock::Text {
                text: text.to_string(),
            });
        } else if let Some(call) = part.get("functionCall") {
            let name = call
                .get("name")
                .and_then(|v| v.as_str())
                .unwrap_or_default()
                .to_string();
            // Gemini doesn't assign call ids; the name is unique enough for
            // our single-tool usage pattern, and doubles as the id used to
            // correlate the ToolResult sent back (see
            // `messages_to_gemini_contents`).
            content.push(ContentBlock::ToolUse {
                id: name.clone(),
                name,
                input: call.get("args").cloned().unwrap_or(Value::Null),
            });
        }
    }

