1	//! Naive baseline: one LLM call on raw strategy source, no tool use, no
2	//! empirical check behind the verdict. This is the thing `advanced.rs` has
3	//! to beat -- see `problem.md` §03's workflow comparison table.
4	
5	use anyhow::{Context, Result};
6	use clap::Parser;
7	use frontier_challenge::llm::{Client, Message};
8	use frontier_challenge::telemetry::Trajectory;
9	use std::path::PathBuf;
10	
11	#[derive(Parser)]
12	struct Args {
13	    /// Path to a strategy source file, e.g.
14	    /// src/strategies/forward_window_lookahead.rs
15	    strategy_file: PathBuf,
16	}
17	
18	const SYSTEM_PROMPT: &str = "You are auditing a quantitative trading strategy's Rust source code for data leakage and look-ahead bias -- e.g. features computed from future bars, execution against a return that already happened, or normalization/statistics fit on the whole series instead of only past data. You get ONE look at the source. You cannot run any code or ask for more information. Respond with your verdict as exactly one word on the first line, LEAKY or CLEAN, followed by a short justification.";
19	
20	fn main() -> Result<()> {
21	    dotenvy::dotenv().ok();
22	    let args = Args::parse();
23	
24	    let source = std::fs::read_to_string(&args.strategy_file)
25	        .with_context(|| format!("reading {}", args.strategy_file.display()))?;
26	    let strategy_name = args
27	        .strategy_file
28	        .file_stem()
29	        .and_then(|s| s.to_str())
30	        .unwrap_or("unknown_strategy")
31	        .to_string();
32	
33	    let mut trajectory = Trajectory::new("baseline", &strategy_name);
34	
35	    let client = Client::from_env()?;
36	    let prompt = format!(
37	        "Strategy source ({}):\n\n```rust\n{}\n```",
38	        args.strategy_file.display(),
39	        source
40	    );
41	    trajectory.record_reasoning(format!(
42	        "Single-shot read of {} ({} bytes), no tool use available.",
43	        args.strategy_file.display(),
44	        source.len()
45	    ));
46	
47	    let response = client.send(SYSTEM_PROMPT, &[Message::user_text(&prompt)], &[])?;
48	    trajectory.add_tokens(response.input_tokens, response.output_tokens);
49	
50	    let text = response.text();
51	    let verdict_word = text
52	        .lines()
53	        .next()
54	        .unwrap_or("")
55	        .trim()
