    // shift_test result -- either via a nudge, or the harness running it
    // directly as a last resort -- because that's the one thing the
    // reported verdict actually has to be grounded in.
    for turn in 1..=MAX_TURNS {
        let text = response.text();
        if !text.trim().is_empty() {
            trajectory.record_reasoning(text);
        }

        let calls: Vec<(String, String, Value)> = response
            .tool_uses()
            .iter()
            .map(|(id, name, input)| (id.to_string(), name.to_string(), (*input).clone()))
            .collect();

        if calls.is_empty() {
            if empirical_result.is_some() {
                break; // final answer received after shift_test was used
            }
            if turn == MAX_TURNS {
                trajectory.record_reasoning(
                    "Model never called shift_test. Falling back: the harness runs it directly \
                     so the reported verdict is still empirically grounded, and this failure mode \
                     is surfaced rather than hidden."
                        .to_string(),
                );
                empirical_result = Some(shift_test(&bars, entry.strategy.as_ref()));
                break;
            }
            trajectory.record_reasoning(
                "Model made no tool call this turn; nudging it toward shift_test.".to_string(),
            );
            messages.push(Message::user_text(
                "You have not called shift_test yet. Call it before concluding -- an unverified read is not an audit.",
            ));
            response = client.send(SYSTEM_PROMPT, &messages, &tools)?;
            trajectory.add_tokens(response.input_tokens, response.output_tokens);
            continue;
        }

        messages.push(Message {
            role: "assistant",
            content: response.content,
        });

        let mut result_blocks = Vec::with_capacity(calls.len());
        for (id, name, input) in &calls {
            let content = match name.as_str() {
                "shift_test" => {
                    let hypothesis = input
                        .get("hypothesis")
                        .and_then(|v| v.as_str())
                        .unwrap_or("(no hypothesis stated)")
                        .to_string();
