                    trajectory.record_tool_output(json!({
                        "findings": findings.iter().map(|f| json!({"rule": f.rule, "message": f.message})).collect::<Vec<_>>(),
                    }));
                    if findings.is_empty() {
                        "no static findings (this alone does not prove the strategy clean -- \
