                            .to_string()
                    } else {
                        findings
                            .iter()
                            .map(|f| format!("[{}] {}", f.rule, f.message))
                            .collect::<Vec<_>>()
                            .join("\n")
                    }
                }
                other => format!("unknown tool '{other}'"),
            };
            result_blocks.push(ContentBlock::ToolResult {
                tool_use_id: id.clone(),
                content,
            });
        }
        messages.push(Message {
            role: "user",
            content: result_blocks,
