28	struct Args {
29	    /// Path to a strategy source file, e.g.
30	    /// src/strategies/forward_window_lookahead.rs
31	    strategy_file: PathBuf,
32	}
33	
34	const MAX_TURNS: usize = 4;
35	
36	const SYSTEM_PROMPT: &str = "You are auditing a quantitative trading strategy's Rust source code for data leakage and look-ahead bias -- e.g. features computed from future bars, execution against a return that already happened, or normalization/statistics fit on the whole series instead of only past data. \
37	You have two tools. static_scan is a fast, free, deterministic static-analysis pass over the source (no LLM, no backtest) -- useful for forming or corroborating a hypothesis quickly, but it only catches specific known patterns, so no findings does not by itself prove the strategy is clean. shift_test is the real empirical check: it reruns the actual backtest with the strategy's computed features shifted forward by exactly one bar and reports the Sharpe ratio before and after -- your final verdict must be grounded in this, not in static_scan alone. \
38	An honest strategy's edge is fragile: shifting it degrades performance toward noise. A leaky strategy is often robust to the shift because the contaminating information isn't confined to one bar. But also weigh the ORIGINAL Sharpe on its own merits: this synthetic market has roughly 1% daily volatility and only a small genuine mean-reversion edge, so a Sharpe ratio far beyond what any real signal could sustain here is itself suspicious, even in a case where the shift happens to degrade it a lot. \
39	Form a hypothesis (static_scan can help), call shift_test to empirically verify it, then state your verdict as exactly one word on the first line of your final answer: LEAKY or CLEAN, followed by a short justification referencing the actual numbers returned.";
40	
41	fn shift_test_tool() -> ToolDef {
42	    ToolDef {
43	        name: "shift_test".to_string(),
44	        description: "Reruns the strategy's real backtest against the same deterministic synthetic price series twice: once as coded, once with its computed feature series shifted forward by exactly one bar (a stand-in for 'what if this had to rely on slightly older information'). Returns sharpe_original, sharpe_shifted, and their delta. Takes no strategy identifier -- it always tests the strategy currently under audit.".to_string(),
45	        input_schema: json!({
46	            "type": "object",
47	            "properties": {
48	                "hypothesis": {
49	                    "type": "string",
50	                    "description": "The specific look-ahead mechanism you suspect in the source, stated before running the test."
51	                }
52	            },
53	            "required": ["hypothesis"]
54	        }),
55	    }
56	}
57	
58	fn static_scan_tool() -> ToolDef {
59	    ToolDef {
60	        name: "static_scan".to_string(),
61	        description: "Parses the strategy's own source as a real Rust AST (no execution, no LLM) and checks for three known look-ahead patterns: a window/index bound that reaches forward past the current bar, a statistic computed over the whole series rather than a windowed sub-range, and an execution offset that doesn't wait for the next bar. Returns a list of findings, or none. Fast and free -- a good first move -- but narrow: absence of a finding does not prove the strategy is clean.".to_string(),
62	        input_schema: json!({"type": "object", "properties": {}, "required": []}),
63	    }
64	}
65	
66	fn parse_verdict(text: &str) -> Option<Verdict> {
67	    let first_word = text
68	        .lines()
69	        .next()?
70	        .trim()
71	        .trim_end_matches('.')
72	        .to_uppercase();
73	    if first_word.starts_with("LEAKY") {
74	        Some(Verdict::Leaky)
75	    } else if first_word.starts_with("CLEAN") {
76	        Some(Verdict::Clean)
77	    } else {
78	        None
79	    }
80	}
81	
