//! The real agent: reasoning -> hypothesis (optionally grounded by a fast
//! static scan) -> empirical tool call (`shift_test`) -> verification ->
//! verdict, with a targeted retry when the model's read of the evidence
//! disagrees with the empirically-justified two-signal rule
//! (`verify::audit`) -- see `problem.md` §03 step 4 ("If inconclusive, it
//! explores an alternative hypothesis").
//!
//! Two tools are available: `static_scan` (a fast, free, deterministic AST
//! pass, `static_checks::scan`) and `shift_test` (the real empirical
//! backtest rerun). `static_scan` is optional -- a hint for hypothesis
//! formation, not proof either way. `shift_test` is the one thing a verdict
//! actually has to be grounded in; the loop below nudges toward it and
//! ultimately falls back to running it directly if the model never does.

use anyhow::{Context, Result};
use clap::Parser;
use frontier_challenge::audit_source::strip_comments;
use frontier_challenge::engine::{generate_series, PriceParams};
use frontier_challenge::llm::{Client, ContentBlock, Message, ToolDef};
use frontier_challenge::static_checks;
use frontier_challenge::strategies::find_by_name;
use frontier_challenge::telemetry::Trajectory;
use frontier_challenge::verify::{audit, shift_test, ShiftTestResult, Verdict};
use serde_json::{json, Value};
use std::path::PathBuf;

#[derive(Parser)]
struct Args {
    /// Path to a strategy source file, e.g.
    /// src/strategies/forward_window_lookahead.rs
    strategy_file: PathBuf,
}

const MAX_TURNS: usize = 4;

const SYSTEM_PROMPT: &str = "You are auditing a quantitative trading strategy's Rust source code for data leakage and look-ahead bias -- e.g. features computed from future bars, execution against a return that already happened, or normalization/statistics fit on the whole series instead of only past data. \
You have two tools. static_scan is a fast, free, deterministic static-analysis pass over the source (no LLM, no backtest) -- useful for forming or corroborating a hypothesis quickly, but it only catches specific known patterns, so no findings does not by itself prove the strategy is clean. shift_test is the real empirical check: it reruns the actual backtest with the strategy's computed features shifted forward by exactly one bar and reports the Sharpe ratio before and after -- your final verdict must be grounded in this, not in static_scan alone. \
An honest strategy's edge is fragile: shifting it degrades performance toward noise. A leaky strategy is often robust to the shift because the contaminating information isn't confined to one bar. But also weigh the ORIGINAL Sharpe on its own merits: this synthetic market has roughly 1% daily volatility and only a small genuine mean-reversion edge, so a Sharpe ratio far beyond what any real signal could sustain here is itself suspicious, even in a case where the shift happens to degrade it a lot. \
Form a hypothesis (static_scan can help), call shift_test to empirically verify it, then state your verdict as exactly one word on the first line of your final answer: LEAKY or CLEAN, followed by a short justification referencing the actual numbers returned.";

fn shift_test_tool() -> ToolDef {
    ToolDef {
        name: "shift_test".to_string(),
        description: "Reruns the strategy's real backtest against the same deterministic synthetic price series twice: once as coded, once with its computed feature series shifted forward by exactly one bar (a stand-in for 'what if this had to rely on slightly older information'). Returns sharpe_original, sharpe_shifted, and their delta. Takes no strategy identifier -- it always tests the strategy currently under audit.".to_string(),
        input_schema: json!({
            "type": "object",
            "properties": {
                "hypothesis": {
                    "type": "string",
                    "description": "The specific look-ahead mechanism you suspect in the source, stated before running the test."
                }
            },
            "required": ["hypothesis"]
        }),
    }
}

fn static_scan_tool() -> ToolDef {
    ToolDef {
        name: "static_scan".to_string(),
        description: "Parses the strategy's own source as a real Rust AST (no execution, no LLM) and checks for three known look-ahead patterns: a window/index bound that reaches forward past the current bar, a statistic computed over the whole series rather than a windowed sub-range, and an execution offset that doesn't wait for the next bar. Returns a list of findings, or none. Fast and free -- a good first move -- but narrow: absence of a finding does not prove the strategy is clean.".to_string(),
        input_schema: json!({"type": "object", "properties": {}, "required": []}),
    }
}

fn parse_verdict(text: &str) -> Option<Verdict> {
    let first_word = text
        .lines()
        .next()?
        .trim()
        .trim_end_matches('.')
        .to_uppercase();
    if first_word.starts_with("LEAKY") {
        Some(Verdict::Leaky)
    } else if first_word.starts_with("CLEAN") {
        Some(Verdict::Clean)
    } else {
        None
    }
}

fn main() -> Result<()> {
    dotenvy::dotenv().ok();
    let args = Args::parse();

    let source = std::fs::read_to_string(&args.strategy_file)
        .with_context(|| format!("reading {}", args.strategy_file.display()))?;
    let strategy_name = args
        .strategy_file
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("unknown_strategy")
        .to_string();
    let entry = find_by_name(&strategy_name).with_context(|| {
        format!(
            "'{strategy_name}' is not a registered seeded strategy (see strategies::all_strategies); \
             the advanced agent can only empirically verify strategies the harness knows how to rerun."
        )
    })?;

    let mut trajectory = Trajectory::new("advanced", &strategy_name);
    let client = Client::from_env()?;
    let bars = generate_series(PriceParams::default());
    let tools = vec![shift_test_tool(), static_scan_tool()];

    // Comments are stripped, and the file path/name is never included in
    // the prompt: both would otherwise hand the LLM a spoiler (e.g. a doc
    // comment or a struct name literally admitting "leaky") that trivializes
    // "detection" and invalidates the whole baseline-vs-advanced comparison.
    // See CHANGELOG for how this was found.
    let sanitized_source = strip_comments(&source);

    let user_prompt = format!(
        "Strategy source:\n\n```rust\n{sanitized_source}\n```\n\nInspect this for look-ahead bias or data leakage. State your initial hypothesis, then call shift_test to empirically verify it before concluding."
    );
    trajectory.record_reasoning(format!(
        "Read a {}-byte strategy (comments stripped before showing the LLM); two tools are available (static_scan, shift_test).",
        sanitized_source.len()
    ));

    let mut messages = vec![Message::user_text(&user_prompt)];
    let mut empirical_result: Option<ShiftTestResult> = None;

    let mut response = client.send(SYSTEM_PROMPT, &messages, &tools)?;
    trajectory.add_tokens(response.input_tokens, response.output_tokens);

    // The API allows a single turn to contain multiple tool_use blocks
    // (parallel tool use), so each round executes *all* calls the model
    // made and returns all their results in one message, not just the
    // first. Bounded to MAX_TURNS round-trips; a model that keeps calling

pub mod execution_timing_mismatch;
pub mod forward_window_lookahead;
pub mod global_normalization_leak;
pub mod honest_mean_reversion;
pub mod honest_trailing_window;

use crate::engine::Strategy;

/// Mean of `closes[end_inclusive - window + 1 ..= end_inclusive]`. Shared by
/// `execution_timing_mismatch::ExecutionTimingMismatch` and
/// `honest_trailing_window::HonestTrailingWindow`, which are deliberately
/// built from the *identical* trailing-window feature -- the only thing
/// that separates the honest strategy from the buggy one is
/// `execution_offset` (1 vs 0), not the feature math itself.
pub(crate) fn trailing_mean(closes: &[f64], end_inclusive: usize, window: usize) -> f64 {
    let start = end_inclusive.saturating_sub(window - 1);
    let slice = &closes[start..=end_inclusive];
    slice.iter().sum::<f64>() / slice.len() as f64
}

