1	//! Deterministic synthetic OHLCV price generator.
2	//!
3	//! The return-generating process is a mean-reverting AR(1) on log returns:
4	//! `r[t] = mu + phi * r[t-1] + sigma * z[t]`, with `phi` slightly negative.
5	//! This gives a small, genuine, exploitable edge (real predictability from the
6	//! previous bar's already-known return) without straying far from a random
7	//! walk -- which is what makes a leakage-inflated Sharpe ratio stand out as
8	//! implausible against a clean strategy's modest one.
9	
10	use rand::{Rng, SeedableRng};
11	use rand_chacha::ChaCha8Rng;
12	
13	#[derive(Debug, Clone, Copy, PartialEq)]
14	pub struct Bar {
15	    pub open: f64,
16	    pub high: f64,
17	    pub low: f64,
18	    pub close: f64,
19	    pub volume: f64,
20	}
21	
22	#[derive(Debug, Clone, Copy)]
23	pub struct PriceParams {
24	    pub seed: u64,
25	    pub n_bars: usize,
26	    pub mu: f64,
27	    pub phi: f64,
28	    pub sigma: f64,
29	    pub start_price: f64,
30	}
31	
32	impl Default for PriceParams {
33	    fn default() -> Self {
34	        PriceParams {
35	            seed: 42,
36	            n_bars: 5000,
37	            mu: 0.0002,
38	            phi: -0.12,
39	            sigma: 0.01,
40	            start_price: 100.0,
41	        }
42	    }
43	}
44	
45	/// Box-Muller transform for a standard normal draw from two uniforms.
46	fn standard_normal(rng: &mut ChaCha8Rng) -> f64 {
47	    let u1: f64 = rng.gen_range(f64::EPSILON..1.0);
48	    let u2: f64 = rng.gen_range(0.0..1.0);
49	    (-2.0 * u1.ln()).sqrt() * (2.0 * std::f64::consts::PI * u2).cos()
50	}
51	
