130	    // first. Bounded to MAX_TURNS round-trips; a model that keeps calling
131	    // static_scan without ever reaching for shift_test still gets a
132	    // shift_test result -- either via a nudge, or the harness running it
133	    // directly as a last resort -- because that's the one thing the
134	    // reported verdict actually has to be grounded in.
135	    for turn in 1..=MAX_TURNS {
136	        let text = response.text();
137	        if !text.trim().is_empty() {
138	            trajectory.record_reasoning(text);
139	        }
140	
