145	            .collect();
146	
147	        if calls.is_empty() {
148	            if empirical_result.is_some() {
149	                break; // final answer received after shift_test was used
150	            }
151	            if turn == MAX_TURNS {
152	                trajectory.record_reasoning(
153	                    "Model never called shift_test. Falling back: the harness runs it directly \
154	                     so the reported verdict is still empirically grounded, and this failure mode \
155	                     is surfaced rather than hidden."
156	                        .to_string(),
157	                );
158	                empirical_result = Some(shift_test(&bars, entry.strategy.as_ref()));
159	                break;
160	            }
161	            trajectory.record_reasoning(
162	                "Model made no tool call this turn; nudging it toward shift_test.".to_string(),
163	            );
164	            messages.push(Message::user_text(
165	                "You have not called shift_test yet. Call it before concluding -- an unverified read is not an audit.",
166	            ));
167	            response = client.send(SYSTEM_PROMPT, &messages, &tools)?;
168	            trajectory.add_tokens(response.input_tokens, response.output_tokens);
169	            continue;
170	        }
171	
172	        messages.push(Message {
173	            role: "assistant",
174	            content: response.content,
175	        });
176	
177	        let mut result_blocks = Vec::with_capacity(calls.len());
178	        for (id, name, input) in &calls {
179	            let content = match name.as_str() {
180	                "shift_test" => {
181	                    let hypothesis = input
182	                        .get("hypothesis")
183	                        .and_then(|v| v.as_str())
184	                        .unwrap_or("(no hypothesis stated)")
185	                        .to_string();
186	                    trajectory.record_tool_call(
187	                        "shift_test",
188	                        json!({"strategy": strategy_name, "hypothesis": hypothesis}),
189	                    );
190	                    let result = shift_test(&bars, entry.strategy.as_ref());
191	                    trajectory.record_tool_output(json!({
192	                        "sharpe_original": result.sharpe_original,
193	                        "sharpe_shifted": result.sharpe_shifted,
194	                        "delta": result.delta,
195	                    }));
196	                    let text = format!(
197	                        "sharpe_original={:.3} sharpe_shifted={:.3} delta={:.3}",
198	                        result.sharpe_original, result.sharpe_shifted, result.delta
199	                    );
200	                    empirical_result = Some(result);
201	                    text
202	                }
203	                "static_scan" => {
204	                    trajectory.record_tool_call("static_scan", json!({"strategy": strategy_name}));
205	                    let findings = static_checks::scan(&sanitized_source).unwrap_or_default();
206	                    trajectory.record_tool_output(json!({
207	                        "findings": findings.iter().map(|f| json!({"rule": f.rule, "message": f.message})).collect::<Vec<_>>(),
208	                    }));
209	                    if findings.is_empty() {
210	                        "no static findings (this alone does not prove the strategy clean -- \
211	                         these are narrow, specific patterns, not a general leakage prover)"
212	                            .to_string()
213	                    } else {
214	                        findings
215	                            .iter()
216	                            .map(|f| format!("[{}] {}", f.rule, f.message))
217	                            .collect::<Vec<_>>()
218	                            .join("\n")
219	                    }
220	                }
221	                other => format!("unknown tool '{other}'"),
222	            };
223	            result_blocks.push(ContentBlock::ToolResult {
224	                tool_use_id: id.clone(),
225	                content,
226	            });
227	        }
228	        messages.push(Message {
229	            role: "user",
230	            content: result_blocks,
231	        });
232	
233	        response = client.send(SYSTEM_PROMPT, &messages, &tools)?;
234	        trajectory.add_tokens(response.input_tokens, response.output_tokens);
235	
236	        if turn == MAX_TURNS && empirical_result.is_none() {
237	            empirical_result = Some(shift_test(&bars, entry.strategy.as_ref()));
238	        }
239	    }
240	
241	    let empirical_result = empirical_result.context("no shift-test result available")?;
242	    let empirical_verdict = audit(&empirical_result);
243	    trajectory.record_verification(format!(
244	        "shift_test: sharpe_original={:.3} sharpe_shifted={:.3} delta={:.3} -> two-signal rule says {:?}",
245	        empirical_result.sharpe_original,
246	        empirical_result.sharpe_shifted,
247	        empirical_result.delta,
248	        empirical_verdict
249	    ));
