1	//! Naive baseline: one LLM call on raw strategy source, no tool use, no
2	//! empirical check behind the verdict. This is the thing `advanced.rs` has
3	//! to beat -- see `problem.md` §03's workflow comparison table.
4	
5	use anyhow::{Context, Result};
6	use clap::Parser;
7	use frontier_challenge::audit_source::strip_comments;
8	use frontier_challenge::llm::{Client, Message};
9	use frontier_challenge::telemetry::Trajectory;
10	use std::path::PathBuf;
11	
12	#[derive(Parser)]
13	struct Args {
14	    /// Path to a strategy source file, e.g.
15	    /// src/strategies/forward_window_lookahead.rs
16	    strategy_file: PathBuf,
17	}
18	
19	const SYSTEM_PROMPT: &str = "You are auditing a quantitative trading strategy's Rust source code for data leakage and look-ahead bias -- e.g. features computed from future bars, execution against a return that already happened, or normalization/statistics fit on the whole series instead of only past data. You get ONE look at the source. You cannot run any code or ask for more information. Respond with your verdict as exactly one word on the first line, LEAKY or CLEAN, followed by a short justification.";
20	
21	fn main() -> Result<()> {
22	    dotenvy::dotenv().ok();
23	    let args = Args::parse();
24	
25	    let source = std::fs::read_to_string(&args.strategy_file)
26	        .with_context(|| format!("reading {}", args.strategy_file.display()))?;
27	    let strategy_name = args
28	        .strategy_file
29	        .file_stem()
30	        .and_then(|s| s.to_str())
31	        .unwrap_or("unknown_strategy")
