1	//! The shift-test verifier: the one empirical tool both binaries call into.
2	//!
3	//! Perturbation: shift the strategy's own computed feature series forward by
4	//! exactly one bar (`shifted[i] = feature[i-1]`) and rerun the backtest with
5	//! the strategy's execution offset unchanged, then compare Sharpe ratios.
6	//!
7	//! This single perturbation is enough to catch two of our three seeded bug
8	//! categories (`ForwardWindowLookahead`, `GlobalNormalizationLeak`): their
9	//! leaks are *persistent* across a one-bar reindex, so Sharpe stays robust.
10	//! It structurally cannot catch the third (`ExecutionTimingMismatch`): that
11	//! bug is itself an exactly-one-bar offset error, and shifting the feature
12	//! array by exactly one bar happens to repair it, collapsing its Sharpe just
13	//! like a clean strategy's. See `audit` below for how we cover that blind
14	//! spot, and `CHANGELOG.md` for the empirical numbers that justify the
15	//! thresholds chosen here.
16	
17	use crate::engine::backtest::run_backtest_from_features;
18	use crate::engine::{Bar, Strategy};
19	
20	#[derive(Debug, Clone, Copy)]
21	pub struct ShiftTestResult {
22	    pub sharpe_original: f64,
23	    pub sharpe_shifted: f64,
24	    /// `sharpe_original - sharpe_shifted`. Large and positive = collapsed
25	    /// under perturbation. Near zero (or negative) = stayed robust.
26	    pub delta: f64,
27	}
28	
29	/// Shifts `feature` forward by one bar: `shifted[i] = feature[i-1]`,
30	/// `shifted[0] = 0.0` (bar 0 never contributes to realized PnL regardless of
31	/// execution offset, so its value is unused).
32	fn shift_forward_one_bar(feature: &[f64]) -> Vec<f64> {
33	    let mut shifted = vec![0.0; feature.len()];
34	    if !feature.is_empty() {
35	        shifted[1..].copy_from_slice(&feature[..feature.len() - 1]);
36	    }
37	    shifted
38	}
39	
40	/// Runs `feature` under both its original and one-bar-shifted form and
41	/// reports the Sharpe delta. Pure and strategy-agnostic -- `shift_test`
42	/// below is a thin wrapper over this using a strategy's own whole feature
43	/// vector; `localize` reuses it directly on individual named components.
44	fn shift_test_on_feature(bars: &[Bar], feature: &[f64], offset: usize) -> ShiftTestResult {
45	    let original = run_backtest_from_features(bars, feature, offset);
46	    let shifted_feature = shift_forward_one_bar(feature);
47	    let shifted = run_backtest_from_features(bars, &shifted_feature, offset);
48	
49	    ShiftTestResult {
50	        sharpe_original: original.sharpe,
51	        sharpe_shifted: shifted.sharpe,
52	        delta: original.sharpe - shifted.sharpe,
53	    }
54	}
55	
56	/// Runs the strategy under both the original and one-bar-shifted feature
57	/// series and reports the Sharpe delta. This is the one tool `advanced.rs`
58	/// calls into to empirically verify (or falsify) a leakage hypothesis.
59	pub fn shift_test(bars: &[Bar], strategy: &dyn Strategy) -> ShiftTestResult {
60	    shift_test_on_feature(
61	        bars,
62	        &strategy.compute_features(bars),
63	        strategy.execution_offset(),
64	    )
65	}
66	
67	/// Runs `shift_test`'s perturbation independently on each of a strategy's
68	/// named feature components (see `Strategy::feature_components`), so the
69	/// result can point at *which* component carries a leak rather than only
70	/// whether the strategy as a whole does. Reuses `audit`'s existing
71	/// calibrated thresholds directly -- no separate calibration needed, since
72	/// each component is shift-tested exactly the way a whole feature vector
73	/// is. Strategies that don't override `feature_components` get back a
74	/// single entry identical to `shift_test`'s own result.
75	pub fn localize(
76	    bars: &[Bar],
77	    strategy: &dyn Strategy,
78	) -> Vec<(&'static str, ShiftTestResult, Verdict)> {
79	    let offset = strategy.execution_offset();
80	    strategy
81	        .feature_components(bars)
82	        .into_iter()
83	        .map(|(name, component)| {
84	            let result = shift_test_on_feature(bars, &component, offset);
85	            let verdict = audit(&result);
86	            (name, result, verdict)
87	        })
88	        .collect()
89	}
90	
91	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
92	pub enum Verdict {
93	    Leaky,
94	    Clean,
95	}
96	
97	/// Empirically justified thresholds (see `CHANGELOG.md` Iteration 3 for the
98	/// measured Sharpe table these were picked from):
99	///
100	/// - `DELTA_ROBUSTNESS_THRESHOLD`: below this, the shift barely dented
101	///   performance -> primary leak signal. Clean controls collapse by several
102	///   Sharpe points under shift; leaky strategies with a persistent leak drop
103	///   by well under one point. `1.0` sits between the two clusters.
104	/// - `IMPLAUSIBLE_SHARPE_CEILING`: catches `ExecutionTimingMismatch`, whose
105	///   leak the shift-test's own perturbation happens to repair (see module
106	///   docs). No legitimate strategy on this synthetic generator clears this
107	///   Sharpe -- it is calibrated well above the honest controls' range.
108	pub const DELTA_ROBUSTNESS_THRESHOLD: f64 = 1.0;
109	pub const IMPLAUSIBLE_SHARPE_CEILING: f64 = 3.0;
110	
111	/// The two-signal verdict rule described above. `advanced.rs` uses this as
112	/// its second hypothesis when the shift-test delta alone is ambiguous; see
113	/// `problem.md` §03 step 4 ("If inconclusive, it explores an alternative
114	/// hypothesis") -- this ceiling *is* that alternative hypothesis.
115	pub fn audit(result: &ShiftTestResult) -> Verdict {
116	    let robust_under_shift = result.delta < DELTA_ROBUSTNESS_THRESHOLD;
117	    let implausibly_high = result.sharpe_original > IMPLAUSIBLE_SHARPE_CEILING;
118	    if robust_under_shift || implausibly_high {
119	        Verdict::Leaky
120	    } else {
121	        Verdict::Clean
122	    }
123	}
124	
125	/// What `advanced.rs` actually reports, as distinct from [`Verdict`] (the
126	/// pure empirical primitive above, which stays binary and untouched). Adds
127	/// a third state for when the agent's two tools genuinely disagree.
128	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
129	pub enum AgentVerdict {
130	    Leaky,
131	    Clean,
132	    Inconclusive,
133	}
134	
135	/// Combines `static_scan`'s hint with `shift_test`'s empirical verdict into
136	/// what the agent should report.
137	///
138	/// Absence of a static finding is never a signal either way -- the static
139	/// layer is documented as narrow, so "no findings" never claims clean. The
140	/// one genuine conflict worth surfacing is the opposite case: `static_scan`
141	/// positively flagged something, but the empirical two-signal rule -- the
142	/// thing a verdict actually has to be grounded in -- came back Clean
143	/// anyway. That specific combination is reported as `Inconclusive` rather
144	/// than silently deferring to the empirical side, which is what happened
145	/// before this existed.
146	pub fn combine_signals(static_findings_present: bool, empirical: Verdict) -> AgentVerdict {
147	    match (static_findings_present, empirical) {
148	        (true, Verdict::Clean) => AgentVerdict::Inconclusive,
149	        (_, Verdict::Leaky) => AgentVerdict::Leaky,
150	        (false, Verdict::Clean) => AgentVerdict::Clean,
151	    }
152	}
