1	//! The real agent: reasoning -> hypothesis (optionally grounded by a fast
2	//! static scan) -> empirical tool call (`shift_test`) -> verification ->
3	//! verdict, with a targeted retry when the model's read of the evidence
4	//! disagrees with the empirically-justified two-signal rule
5	//! (`verify::audit`) -- see `problem.md` §03 step 4 ("If inconclusive, it
6	//! explores an alternative hypothesis").
7	//!
8	//! Two tools are available: `static_scan` (a fast, free, deterministic AST
9	//! pass, `static_checks::scan`) and `shift_test` (the real empirical
10	//! backtest rerun). `static_scan` is optional -- a hint for hypothesis
11	//! formation, not proof either way. `shift_test` is the one thing a verdict
12	//! actually has to be grounded in; the loop below nudges toward it and
13	//! ultimately falls back to running it directly if the model never does.
14	
15	use anyhow::{Context, Result};
16	use clap::Parser;
17	use frontier_challenge::audit_source::strip_comments;
18	use frontier_challenge::engine::{generate_series, PriceParams};
19	use frontier_challenge::llm::{Client, ContentBlock, Message, ToolDef};
20	use frontier_challenge::static_checks;
21	use frontier_challenge::strategies::find_by_name;
22	use frontier_challenge::telemetry::Trajectory;
23	use frontier_challenge::verify::{
24	    audit, combine_signals, localize, shift_test, AgentVerdict, ShiftTestResult,
25	};
26	use serde_json::{json, Value};
27	use std::path::PathBuf;
28	
29	#[derive(Parser)]
30	struct Args {
31	    /// Path to a strategy source file, e.g.
32	    /// src/strategies/forward_window_lookahead.rs
33	    strategy_file: PathBuf,
34	}
35	
36	const MAX_TURNS: usize = 4;
37	
38	const SYSTEM_PROMPT: &str = "You are auditing a quantitative trading strategy's Rust source code for data leakage and look-ahead bias -- e.g. features computed from future bars, execution against a return that already happened, or normalization/statistics fit on the whole series instead of only past data. \
39	You have two tools. static_scan is a fast, free, deterministic static-analysis pass over the source (no LLM, no backtest) -- useful for forming or corroborating a hypothesis quickly, but it only catches specific known patterns, so no findings does not by itself prove the strategy is clean. shift_test is the real empirical check: it reruns the actual backtest with the strategy's computed features shifted forward by exactly one bar and reports the Sharpe ratio before and after -- your final verdict must be grounded in this, not in static_scan alone. \
40	An honest strategy's edge is fragile: shifting it degrades performance toward noise. A leaky strategy is often robust to the shift because the contaminating information isn't confined to one bar. But also weigh the ORIGINAL Sharpe on its own merits: this synthetic market has roughly 1% daily volatility and only a small genuine mean-reversion edge, so a Sharpe ratio far beyond what any real signal could sustain here is itself suspicious, even in a case where the shift happens to degrade it a lot. \
41	Form a hypothesis (static_scan can help), call shift_test to empirically verify it, then state your verdict as exactly one word on the first line of your final answer: LEAKY or CLEAN, followed by a short justification referencing the actual numbers returned. If static_scan flags a real pattern but shift_test shows the strategy is robust to Sharpe-collapse, that is a genuine disagreement between your tools -- say so plainly (you may answer INCONCLUSIVE) rather than forcing a confident pick either way.";
42	
43	fn shift_test_tool() -> ToolDef {
44	    ToolDef {
45	        name: "shift_test".to_string(),
46	        description: "Reruns the strategy's real backtest against the same deterministic synthetic price series twice: once as coded, once with its computed feature series shifted forward by exactly one bar (a stand-in for 'what if this had to rely on slightly older information'). Returns sharpe_original, sharpe_shifted, and their delta. When the strategy's feature is built from more than one named sub-computation, also returns a per-feature breakdown pointing at which specific component carries a leak, not just whether one exists somewhere in the combined feature. Takes no strategy identifier -- it always tests the strategy currently under audit.".to_string(),
47	        input_schema: json!({
48	            "type": "object",
49	            "properties": {
50	                "hypothesis": {
51	                    "type": "string",
52	                    "description": "The specific look-ahead mechanism you suspect in the source, stated before running the test."
53	                }
54	            },
55	            "required": ["hypothesis"]
56	        }),
57	    }
58	}
59	
60	fn static_scan_tool() -> ToolDef {
61	    ToolDef {
62	        name: "static_scan".to_string(),
63	        description: "Parses the strategy's own source as a real Rust AST (no execution, no LLM) and checks for three known look-ahead patterns: a window/index bound that reaches forward past the current bar, a statistic computed over the whole series rather than a windowed sub-range, and an execution offset that doesn't wait for the next bar. Returns a list of findings, or none. Fast and free -- a good first move -- but narrow: absence of a finding does not prove the strategy is clean.".to_string(),
64	        input_schema: json!({"type": "object", "properties": {}, "required": []}),
65	    }
66	}
67	
68	fn parse_verdict(text: &str) -> Option<AgentVerdict> {
69	    let first_word = text
70	        .lines()
71	        .next()?
72	        .trim()
73	        .trim_end_matches('.')
74	        .to_uppercase();
75	    if first_word.starts_with("LEAKY") {
76	        Some(AgentVerdict::Leaky)
77	    } else if first_word.starts_with("CLEAN") {
78	        Some(AgentVerdict::Clean)
79	    } else if first_word.starts_with("INCONCLUSIVE") {
80	        Some(AgentVerdict::Inconclusive)
81	    } else {
82	        None
83	    }
84	}
85	
86	fn main() -> Result<()> {
87	    dotenvy::dotenv().ok();
88	    let args = Args::parse();
89	
90	    let source = std::fs::read_to_string(&args.strategy_file)
91	        .with_context(|| format!("reading {}", args.strategy_file.display()))?;
92	    let strategy_name = args
93	        .strategy_file
94	        .file_stem()
95	        .and_then(|s| s.to_str())
96	        .unwrap_or("unknown_strategy")
97	        .to_string();
98	    let entry = find_by_name(&strategy_name).with_context(|| {
99	        format!(
100	            "'{strategy_name}' is not a registered seeded strategy (see strategies::all_strategies); \
101	             the advanced agent can only empirically verify strategies the harness knows how to rerun."
102	        )
103	    })?;
104	
105	    let mut trajectory = Trajectory::new("advanced", &strategy_name);
106	    let client = Client::from_env()?;
107	    let bars = generate_series(PriceParams::default());
108	    let tools = vec![shift_test_tool(), static_scan_tool()];
109	
110	    // Comments are stripped, and the file path/name is never included in
111	    // the prompt: both would otherwise hand the LLM a spoiler (e.g. a doc
112	    // comment or a struct name literally admitting "leaky") that trivializes
113	    // "detection" and invalidates the whole baseline-vs-advanced comparison.
114	    // See CHANGELOG for how this was found.
115	    let sanitized_source = strip_comments(&source);
116	
117	    let user_prompt = format!(
118	        "Strategy source:\n\n```rust\n{sanitized_source}\n```\n\nInspect this for look-ahead bias or data leakage. State your initial hypothesis, then call shift_test to empirically verify it before concluding."
119	    );
120	    trajectory.record_reasoning(format!(
121	        "Read a {}-byte strategy (comments stripped before showing the LLM); two tools are available (static_scan, shift_test).",
122	        sanitized_source.len()
123	    ));
124	
125	    let mut messages = vec![Message::user_text(&user_prompt)];
126	    let mut empirical_result: Option<ShiftTestResult> = None;
127	    let mut static_findings_present = false;
128	
129	    let mut response = client.send(SYSTEM_PROMPT, &messages, &tools)?;
130	    trajectory.add_tokens(response.input_tokens, response.output_tokens);
131	
132	    // The API allows a single turn to contain multiple tool_use blocks
133	    // (parallel tool use), so each round executes *all* calls the model
134	    // made and returns all their results in one message, not just the
135	    // first. Bounded to MAX_TURNS round-trips; a model that keeps calling
136	    // static_scan without ever reaching for shift_test still gets a
137	    // shift_test result -- either via a nudge, or the harness running it
138	    // directly as a last resort -- because that's the one thing the
139	    // reported verdict actually has to be grounded in.
140	    for turn in 1..=MAX_TURNS {
141	        let text = response.text();
142	        if !text.trim().is_empty() {
143	            trajectory.record_reasoning(text);
144	        }
145	
146	        let calls: Vec<(String, String, Value)> = response
147	            .tool_uses()
148	            .iter()
149	            .map(|(id, name, input)| (id.to_string(), name.to_string(), (*input).clone()))
150	            .collect();
151	
152	        if calls.is_empty() {
153	            if empirical_result.is_some() {
154	                break; // final answer received after shift_test was used
155	            }
156	            if turn == MAX_TURNS {
157	                trajectory.record_reasoning(
158	                    "Model never called shift_test. Falling back: the harness runs it directly \
159	                     so the reported verdict is still empirically grounded, and this failure mode \
160	                     is surfaced rather than hidden."
161	                        .to_string(),
162	                );
163	                empirical_result = Some(shift_test(&bars, entry.strategy.as_ref()));
164	                break;
165	            }
166	            trajectory.record_reasoning(
167	                "Model made no tool call this turn; nudging it toward shift_test.".to_string(),
168	            );
169	            messages.push(Message::user_text(
170	                "You have not called shift_test yet. Call it before concluding -- an unverified read is not an audit.",
171	            ));
172	            response = client.send(SYSTEM_PROMPT, &messages, &tools)?;
173	            trajectory.add_tokens(response.input_tokens, response.output_tokens);
174	            continue;
175	        }
176	
177	        messages.push(Message {
178	            role: "assistant",
179	            content: response.content,
180	        });
181	
182	        let mut result_blocks = Vec::with_capacity(calls.len());
183	        for (id, name, input) in &calls {
184	            let content = match name.as_str() {
185	                "shift_test" => {
186	                    let hypothesis = input
187	                        .get("hypothesis")
188	                        .and_then(|v| v.as_str())
189	                        .unwrap_or("(no hypothesis stated)")
190	                        .to_string();
191	                    trajectory.record_tool_call(
192	                        "shift_test",
193	                        json!({"strategy": strategy_name, "hypothesis": hypothesis}),
194	                    );
195	                    let result = shift_test(&bars, entry.strategy.as_ref());
196	                    let components = localize(&bars, entry.strategy.as_ref());
197	                    trajectory.record_tool_output(json!({
198	                        "sharpe_original": result.sharpe_original,
199	                        "sharpe_shifted": result.sharpe_shifted,
200	                        "delta": result.delta,
201	                        "components": components.iter().map(|(name, r, v)| json!({
202	                            "name": name, "delta": r.delta, "verdict": format!("{v:?}"),
203	                        })).collect::<Vec<_>>(),
204	                    }));
205	                    let mut text = format!(
206	                        "sharpe_original={:.3} sharpe_shifted={:.3} delta={:.3}",
207	                        result.sharpe_original, result.sharpe_shifted, result.delta
208	                    );
209	                    // Localization: when this strategy's feature is built
210	                    // from more than one named component, shift-test each
211	                    // independently so the report can point at which one
212	                    // actually carries the leak, not just that one exists
213	                    // somewhere in the combined feature.
214	                    if components.len() > 1 {
215	                        text.push_str("\n\nper-feature breakdown:");
216	                        for (name, r, verdict) in &components {
217	                            text.push_str(&format!(
218	                                "\n- {name}: delta={:.3} -> {verdict:?}",
219	                                r.delta
220	                            ));
221	                        }
222	                    }
223	                    empirical_result = Some(result);
224	                    text
225	                }
226	                "static_scan" => {
227	                    trajectory.record_tool_call("static_scan", json!({"strategy": strategy_name}));
228	                    let findings = static_checks::scan(&sanitized_source).unwrap_or_default();
229	                    trajectory.record_tool_output(json!({
230	                        "findings": findings.iter().map(|f| json!({"rule": f.rule, "message": f.message})).collect::<Vec<_>>(),
231	                    }));
232	                    static_findings_present = static_findings_present || !findings.is_empty();
233	                    if findings.is_empty() {
234	                        "no static findings (this alone does not prove the strategy clean -- \
235	                         these are narrow, specific patterns, not a general leakage prover)"
236	                            .to_string()
237	                    } else {
238	                        findings
239	                            .iter()
240	                            .map(|f| format!("[{}] {}", f.rule, f.message))
241	                            .collect::<Vec<_>>()
242	                            .join("\n")
243	                    }
244	                }
245	                other => format!("unknown tool '{other}'"),
246	            };
247	            result_blocks.push(ContentBlock::ToolResult {
248	                tool_use_id: id.clone(),
249	                content,
250	            });
251	        }
252	        messages.push(Message {
253	            role: "user",
254	            content: result_blocks,
255	        });
256	
257	        response = client.send(SYSTEM_PROMPT, &messages, &tools)?;
258	        trajectory.add_tokens(response.input_tokens, response.output_tokens);
259	
260	        if turn == MAX_TURNS && empirical_result.is_none() {
261	            empirical_result = Some(shift_test(&bars, entry.strategy.as_ref()));
262	        }
263	    }
264	
265	    let empirical_result = empirical_result.context("no shift-test result available")?;
266	    let empirical_verdict = audit(&empirical_result);
267	    trajectory.record_verification(format!(
268	        "shift_test: sharpe_original={:.3} sharpe_shifted={:.3} delta={:.3} -> two-signal rule says {:?}",
269	        empirical_result.sharpe_original,
270	        empirical_result.sharpe_shifted,
271	        empirical_result.delta,
272	        empirical_verdict
273	    ));
274	
275	    // What the two tools together imply the agent should report -- Leaky or
276	    // Clean when they agree (or static_scan found nothing, its normal
277	    // silent case), Inconclusive on a genuine conflict: static_scan flagged
278	    // something but the empirical rule came back Clean anyway.
279	    let signal_verdict = combine_signals(static_findings_present, empirical_verdict);
280	    if signal_verdict == AgentVerdict::Inconclusive {
281	        trajectory.record_verification(format!(
282	            "static_scan flagged a pattern but the empirical rule says Clean -- signals disagree, reporting Inconclusive (static_findings_present={static_findings_present})"
283	        ));
284	    }
285	
286	    let mut final_text = response.text();
287	    let mut model_verdict = parse_verdict(&final_text);
288	
289	    // Self-correction: if the model's read disagrees with what the signals
290	    // together imply, give it one more targeted look before finalizing.
291	    // Skipped when the signals themselves are Inconclusive -- there is
292	    // nothing to nudge the model toward matching in that case.
293	    if signal_verdict != AgentVerdict::Inconclusive && model_verdict != Some(signal_verdict) {
294	        trajectory.record_reasoning(format!(
295	            "Model's verdict ({model_verdict:?}) disagrees with the empirical two-signal rule ({empirical_verdict:?}). Offering one alternative-hypothesis pass."
296	        ));
297	        messages.push(Message {
298	            role: "assistant",
299	            content: vec![ContentBlock::Text {
300	                text: final_text.clone(),
301	            }],
302	        });
303	        messages.push(Message::user_text(
304	            "Reconsider: don't judge robustness by the delta alone. Is sharpe_original, taken on its own, plausible for a legitimate signal on ~1% daily volatility synthetic data with only a small real mean-reversion edge -- even in a case where the shift happened to degrade it substantially? State your final verdict as the first line: LEAKY or CLEAN.",
305	        ));
306	        let retry = client.send(SYSTEM_PROMPT, &messages, &tools)?;
307	        trajectory.add_tokens(retry.input_tokens, retry.output_tokens);
308	        final_text = retry.text();
309	        model_verdict = parse_verdict(&final_text);
310	        trajectory.record_verification(format!("alternate-hypothesis pass -> {model_verdict:?}"));
311	    }
312	
313	    let (reported_verdict, confidence) = if signal_verdict == AgentVerdict::Inconclusive {
314	        (
315	            AgentVerdict::Inconclusive,
316	            format!(
317	                "inconclusive: static_scan flagged a pattern but shift_test's empirical rule \
318	                 (delta={:.3}, sharpe_original={:.3}) found the strategy robust to Sharpe-collapse \
319	                 -- signals disagree, not confidently resolved either way",
320	                empirical_result.delta, empirical_result.sharpe_original
321	            ),
322	        )
323	    } else {
324	        let verdict = model_verdict.unwrap_or(signal_verdict);
325	        let confidence = if model_verdict == Some(signal_verdict) {
326	            "model agrees with empirical rule".to_string()
327	        } else if model_verdict.is_none() {
328	            "model gave no parseable verdict; fell back to empirical rule".to_string()
329	        } else {
330	            "model disagrees with empirical rule after retry; reporting model's stated verdict"
331	                .to_string()
332	        };
333	        (verdict, confidence)
334	    };
335	    trajectory.record_final_verdict(
336	        format!("{reported_verdict:?}").to_uppercase(),
337	        empirical_result.delta,
338	        confidence,
339	    );
340	
341	    println!("strategy: {strategy_name}");
342	    println!(
343	        "shift-test: sharpe_original={:.3} sharpe_shifted={:.3} delta={:.3}",
344	        empirical_result.sharpe_original, empirical_result.sharpe_shifted, empirical_result.delta
345	    );
346	    println!("empirical rule verdict: {empirical_verdict:?}");
347	    println!("agent verdict:          {reported_verdict:?}");
348	    // Machine-parseable line for tests/acceptance.rs; kept separate from the
349	    // human-readable line above so reformatting that one can't break parsing.
350	    println!(
351	        "VERDICT: {}",
352	        match reported_verdict {
353	            AgentVerdict::Leaky => "LEAKY",
354	            AgentVerdict::Clean => "CLEAN",
355	            AgentVerdict::Inconclusive => "INCONCLUSIVE",
356	        }
357	    );
358	    println!("\n--- model's final answer ---\n{final_text}");
359	
