1	//! Evaluation harness: runs both `baseline` and `advanced` against every
2	//! seeded strategy and reports detection accuracy -- the "Measured
3	//! Improvement" evidence in agents.md's Definition of Done.
4	//!
5	//! This test makes real LLM API calls and costs real money, so it is
6	//! opt-in: it skips (not fails) when no API key is configured for the
7	//! active `LLM_PROVIDER`, keeping a plain `cargo test` free and fully
8	//! offline. Set the relevant key (see .env.example) and run
9	//! `cargo test --test acceptance -- --nocapture` to see the accuracy table.
10	//! Each invocation writes its own trajectory file to trajectories/ as a
11	//! side effect (via the telemetry module both binaries use), satisfying the
12	//! "trajectories/ contains a trace for every seeded strategy, for both
13	//! binaries" Definition of Done item.
14	
15	use frontier_challenge::strategies::all_strategies;
16	use frontier_challenge::verify::AgentVerdict;
17	use std::process::Command;
18	
19	/// Treats a set-but-empty variable (`ANTHROPIC_API_KEY=[REDACTED] in a `.env`, which
20	/// `std::env::var` reports as `Ok("")`, not an error) as absent. Mirrors
21	/// `llm::env_var_nonempty`; using a bare `.is_ok()` here made this test
22	/// believe a key was configured and *fail* rather than skip -- see
23	/// CHANGELOG Iteration 5, where the same bug was fixed in the client.
24	fn env_var_nonempty(name: &str) -> bool {
25	    std::env::var(name)
26	        .ok()
27	        .is_some_and(|v| !v.trim().is_empty())
28	}
29	
30	fn active_api_key_is_configured() -> bool {
31	    dotenvy::dotenv().ok();
32	    let provider = std::env::var("LLM_PROVIDER").unwrap_or_else(|_| "anthropic".to_string());
33	    match provider.to_lowercase().as_str() {
34	        "gemini" => env_var_nonempty("GEMINI_API_KEY"),
35	        _ => env_var_nonempty("ANTHROPIC_API_KEY"),
36	    }
37	}
38	
39	/// `None` means no `VERDICT:` line matched any known word -- a genuine
40	/// parse failure. `Inconclusive` is a real, meaningful outcome (advanced
41	/// only, when its two tools disagree -- see `verify::combine_signals`), not
42	/// a parse failure, so it gets its own tally rather than being scored right
43	/// or wrong.
44	fn parse_verdict_line(stdout: &str) -> Option<AgentVerdict> {
45	    for line in stdout.lines() {
46	        if let Some(rest) = line.trim().strip_prefix("VERDICT:") {
47	            let rest = rest.trim();
48	            if rest == "LEAKY" {
49	                return Some(AgentVerdict::Leaky);
50	            }
51	            if rest == "CLEAN" {
52	                return Some(AgentVerdict::Clean);
53	            }
54	            if rest == "INCONCLUSIVE" {
55	                return Some(AgentVerdict::Inconclusive);
56	            }
57	        }
58	    }
59	    None
60	}
61	
62	fn run_binary(bin_path: &str, source_path: &str) -> Option<AgentVerdict> {
63	    let output = Command::new(bin_path)
64	        .arg(source_path)
65	        .current_dir(env!("CARGO_MANIFEST_DIR"))
66	        .output()
67	        .unwrap_or_else(|e| panic!("failed to run {bin_path}: {e}"));
68	    parse_verdict_line(&String::from_utf8_lossy(&output.stdout))
69	}
70	
71	fn expected(is_leaky: bool) -> AgentVerdict {
72	    if is_leaky {
73	        AgentVerdict::Leaky
74	    } else {
75	        AgentVerdict::Clean
76	    }
77	}
