84	             This test makes real, billed LLM calls and is opt-in by design -- \
85	             set ANTHROPIC_API_KEY or GEMINI_API_KEY and rerun with \
86	             `cargo test --test acceptance -- --nocapture` to see the accuracy table."
87	        );
88	        return;
89	    }
