91	    let baseline_bin = env!("CARGO_BIN_EXE_baseline");
92	    let advanced_bin = env!("CARGO_BIN_EXE_advanced");
93	
94	    let mut baseline_correct = 0;
95	    let mut advanced_correct = 0;
96	    let mut advanced_inconclusive = 0;
97	    let mut parse_failures = Vec::new();
98	    let mut total = 0;
99	
100	    println!(
101	        "{:<28} {:>6} {:>10} {:>10}",
102	        "strategy", "truth", "baseline", "advanced"
103	    );
104	    for entry in all_strategies() {
105	        total += 1;
106	        let baseline_verdict = run_binary(baseline_bin, entry.source_path);
107	        let advanced_verdict = run_binary(advanced_bin, entry.source_path);
108	
109	        if baseline_verdict.is_none() {
110	            parse_failures.push(format!("baseline/{}", entry.name));
111	        }
112	        if advanced_verdict.is_none() {
113	            parse_failures.push(format!("advanced/{}", entry.name));
114	        }
115	        if baseline_verdict == Some(expected(entry.is_leaky)) {
116	            baseline_correct += 1;
117	        }
118	        if advanced_verdict == Some(expected(entry.is_leaky)) {
