131	    }
132	
133	    // Inconclusive is excluded from the accuracy denominator -- it's a
134	    // real, meaningful outcome (a genuine tool disagreement), not a wrong
135	    // answer scored against the ground truth the same way Leaky/Clean are.
136	    println!("\nbaseline accuracy: {baseline_correct}/{total}");
137	    println!(
138	        "advanced accuracy: {advanced_correct}/{} ({advanced_inconclusive} inconclusive, not scored)",
139	        total - advanced_inconclusive
