1	//! Trajectory recorder shared by `baseline` and `advanced` -- see
2	//! `agents.md` §4 for the schema and why this is mandatory, not incidental
3	//! logging. Steps are appended live as the binary actually executes them;
4	//! nothing here reconstructs a trace after the fact.
5	
6	use anyhow::{Context, Result};
7	use serde::Serialize;
8	use std::path::{Path, PathBuf};
9	use std::time::Instant;
10	
11	#[derive(Serialize, Default, Clone, Copy)]
12	pub struct TokensUsed {
13	    pub input: u32,
14	    pub output: u32,
15	}
16	
17	#[derive(Serialize)]
18	#[serde(tag = "type")]
19	pub enum TrajectoryStep {
20	    #[serde(rename = "reasoning")]
21	    Reasoning { step: usize, content: String },
22	    #[serde(rename = "tool_call")]
23	    ToolCall {
24	        step: usize,
25	        tool: String,
26	        input: serde_json::Value,
27	    },
28	    #[serde(rename = "tool_output")]
29	    ToolOutput {
30	        step: usize,
31	        output: serde_json::Value,
32	    },
33	    #[serde(rename = "verification")]
34	    Verification { step: usize, content: String },
35	    #[serde(rename = "final_verdict")]
36	    FinalVerdict {
37	        step: usize,
38	        verdict: String,
39	        sharpe_delta: f64,
40	        confidence: String,
41	    },
42	}
43	
44	#[derive(Serialize)]
45	pub struct Trajectory {
46	    pub run_id: String,
47	    pub binary: String,
48	    pub strategy: String,
49	    pub started_at: String,
50	    pub steps: Vec<TrajectoryStep>,
51	    pub tokens_used: TokensUsed,
52	    pub wall_clock_ms: u128,
53	    #[serde(skip)]
54	    start_instant: Instant,
55	    #[serde(skip)]
56	    next_step: usize,
57	}
58	
59	impl Trajectory {
60	    pub fn new(binary: &str, strategy: &str) -> Self {
61	        Trajectory {
62	            run_id: uuid::Uuid::new_v4().to_string(),
63	            binary: binary.to_string(),
64	            strategy: strategy.to_string(),
65	            started_at: chrono::Utc::now().to_rfc3339(),
66	            steps: Vec::new(),
67	            tokens_used: TokensUsed::default(),
68	            wall_clock_ms: 0,
69	            start_instant: Instant::now(),
70	            next_step: 1,
71	        }
72	    }
73	
74	    fn next(&mut self) -> usize {
75	        let s = self.next_step;
76	        self.next_step += 1;
77	        s
78	    }
79	
80	    pub fn record_reasoning(&mut self, content: impl Into<String>) {
81	        let step = self.next();
82	        self.steps.push(TrajectoryStep::Reasoning {
83	            step,
84	            content: content.into(),
85	        });
86	    }
87	
88	    pub fn record_tool_call(&mut self, tool: impl Into<String>, input: serde_json::Value) {
89	        let step = self.next();
90	        self.steps.push(TrajectoryStep::ToolCall {
91	            step,
92	            tool: tool.into(),
93	            input,
94	        });
95	    }
96	
97	    pub fn record_tool_output(&mut self, output: serde_json::Value) {
98	        let step = self.next();
99	        self.steps.push(TrajectoryStep::ToolOutput { step, output });
100	    }
101	
102	    pub fn record_verification(&mut self, content: impl Into<String>) {
103	        let step = self.next();
104	        self.steps.push(TrajectoryStep::Verification {
105	            step,
106	            content: content.into(),
107	        });
108	    }
109	
110	    pub fn record_final_verdict(
111	        &mut self,
112	        verdict: impl Into<String>,
113	        sharpe_delta: f64,
114	        confidence: impl Into<String>,
115	    ) {
116	        let step = self.next();
117	        self.steps.push(TrajectoryStep::FinalVerdict {
118	            step,
119	            verdict: verdict.into(),
120	            sharpe_delta,
121	            confidence: confidence.into(),
122	        });
123	    }
124	
125	    pub fn add_tokens(&mut self, input: u32, output: u32) {
126	        self.tokens_used.input += input;
127	        self.tokens_used.output += output;
128	    }
129	
130	    /// Finalizes wall-clock time and writes the trajectory to
131	    /// `<dir>/<binary>_<strategy>_<unix-timestamp>.json`. Returns the path
132	    /// written, per the naming convention in `agents.md` §4.
133	    pub fn finish_and_write(mut self, dir: &Path) -> Result<PathBuf> {
134	        self.wall_clock_ms = self.start_instant.elapsed().as_millis();
135	        std::fs::create_dir_all(dir)
136	            .with_context(|| format!("creating trajectory dir {}", dir.display()))?;
137	        let unix_ts = chrono::Utc::now().timestamp();
138	        let filename = format!("{}_{}_{}.json", self.binary, self.strategy, unix_ts);
139	        let path = dir.join(filename);
140	        let json = serde_json::to_string_pretty(&self)?;
141	        std::fs::write(&path, json).with_context(|| format!("writing {}", path.display()))?;
142	        Ok(path)
143	    }
144	}
145	
146	#[cfg(test)]
147	mod tests {
148	    use super::*;
149	
150	    #[test]
151	    fn writes_a_trajectory_file_with_recorded_steps() {
152	        let mut traj = Trajectory::new("advanced", "test_strategy");
153	        traj.record_reasoning("suspect a forward-looking window");
154	        traj.record_tool_call("shift_test", serde_json::json!({"shift_bars": 1}));
155	        traj.record_tool_output(serde_json::json!({"sharpe_original": 9.4, "sharpe_shifted": 6.7}));
156	        traj.record_verification("delta below threshold -> leaky");
157	        traj.record_final_verdict("LEAKY", 2.7, "high");
158	        traj.add_tokens(120, 45);
159	
160	        let dir = std::env::temp_dir().join(format!("traj-test-{}", uuid::Uuid::new_v4()));
161	        let path = traj.finish_and_write(&dir).unwrap();
162	        let contents = std::fs::read_to_string(&path).unwrap();
163	        let parsed: serde_json::Value = serde_json::from_str(&contents).unwrap();
164	
165	        assert_eq!(parsed["binary"], "advanced");
166	        assert_eq!(parsed["strategy"], "test_strategy");
167	        assert_eq!(parsed["steps"].as_array().unwrap().len(), 5);
168	        assert_eq!(parsed["steps"][0]["type"], "reasoning");
169	        assert_eq!(parsed["steps"][4]["type"], "final_verdict");
170	        assert_eq!(parsed["tokens_used"]["input"], 120);
171	
172	        std::fs::remove_dir_all(&dir).unwrap();
173	    }
174	}
