1	//! Minimal LLM client supporting two providers (raw HTTP -- there is no
2	//! official Rust SDK for either): Anthropic's Messages API and Google's
3	//! Gemini `generateContent` API. Both binaries program against the
4	//! provider-agnostic `Message`/`ContentBlock`/`ToolDef`/`ApiResponse` types
5	//! below; provider selection and wire-format translation happen entirely
6	//! inside `Client`.
7	
8	use anyhow::{bail, Context, Result};
9	use serde_json::{json, Value};
10	
11	/// Per `claude-api` skill guidance: default to the most capable model
12	/// unless told otherwise. Override with `ANTHROPIC_MODEL` for cost tuning
13	/// (the challenge's "Operational Cost" evaluation dimension) without a
14	/// rebuild.
15	pub const DEFAULT_ANTHROPIC_MODEL: &str = "claude-opus-5";
16	/// A stable, widely-available Gemini model used as the default. Override
17	/// with `GEMINI_MODEL` -- Google ships new model generations faster than
18	/// this file gets updated, so treat this default as a safe fallback, not a
19	/// recommendation to stay on it. `gemini-2.5-flash` was the first choice
20	/// here but its free tier caps at 20 requests/*day*, not per-minute --
21	/// `gemini-3.5-flash-lite` has a much friendlier free-tier quota and is
22	/// what this project was actually evaluated against (see CHANGELOG
23	/// Iteration 5).
24	pub const DEFAULT_GEMINI_MODEL: &str = "gemini-3.5-flash-lite";
25	
26	const ANTHROPIC_API_URL: &str = "https://api.anthropic.com/v1/messages";
27	const ANTHROPIC_VERSION: &str = "2023-06-01";
28	const MAX_TOKENS: u32 = 4096;
29	
30	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
31	pub enum Provider {
32	    Anthropic,
33	    Gemini,
34	}
35	
36	#[derive(Debug, Clone)]
37	pub struct ToolDef {
38	    pub name: String,
39	    pub description: String,
40	    pub input_schema: Value,
41	}
42	
43	#[derive(Debug, Clone)]
44	pub enum ContentBlock {
45	    Text {
46	        text: String,
47	    },
48	    ToolUse {
49	        id: String,
50	        name: String,
51	        input: Value,
52	        /// Gemini-only: an opaque signature Gemini 3.x attaches to a
53	        /// `functionCall` part when thinking produced it. It must be
54	        /// echoed back unchanged on that same part in the next turn, or
55	        /// the API rejects the request with a 400 ("missing a
56	        /// thought_signature"). Always `None` for Anthropic, which has no
57	        /// such requirement.
58	        thought_signature: Option<String>,
59	    },
60	    ToolResult {
61	        tool_use_id: String,
62	        content: String,
63	    },
64	}
65	
66	#[derive(Debug, Clone)]
67	pub struct Message {
68	    pub role: &'static str,
69	    pub content: Vec<ContentBlock>,
70	}
71	
72	impl Message {
73	    pub fn user_text(text: impl Into<String>) -> Self {
74	        Message {
75	            role: "user",
76	            content: vec![ContentBlock::Text { text: text.into() }],
77	        }
78	    }
79	}
80	
81	#[derive(Debug)]
82	pub struct ApiResponse {
83	    pub content: Vec<ContentBlock>,
84	    pub stop_reason: String,
85	    pub input_tokens: u32,
86	    pub output_tokens: u32,
87	}
88	
89	impl ApiResponse {
90	    /// Concatenates every text block, ignoring tool_use blocks. Convenience
91	    /// for the baseline binary, which never expects tool calls back.
92	    pub fn text(&self) -> String {
93	        self.content
94	            .iter()
95	            .filter_map(|b| match b {
96	                ContentBlock::Text { text } => Some(text.as_str()),
97	                _ => None,
98	            })
99	            .collect::<Vec<_>>()
100	            .join("\n")
101	    }
102	
103	    pub fn tool_uses(&self) -> Vec<(&str, &str, &Value)> {
104	        self.content
105	            .iter()
106	            .filter_map(|b| match b {
107	                ContentBlock::ToolUse {
108	                    id, name, input, ..
109	                } => Some((id.as_str(), name.as_str(), input)),
110	                _ => None,
111	            })
112	            .collect()
113	    }
114	}
115	
116	pub struct Client {
117	    provider: Provider,
118	    api_key: String,
119	    model: String,
120	    http: reqwest::blocking::Client,
121	}
122	
123	/// Reads an env var, treating both "unset" and "set but empty" as absent.
124	/// `.env.example`'s convention of leaving optional vars as a bare `KEY=`
125	/// line means `std::env::var` alone would see `Ok("")` for those and never
126	/// fall back to a default -- this is what that convention actually needs.
127	fn env_var_nonempty(name: &str) -> Option<String> {
128	    std::env::var(name).ok().filter(|v| !v.trim().is_empty())
129	}
130	
131	impl Client {
132	    /// Picks a provider from `LLM_PROVIDER` (`"anthropic"` (default) or
133	    /// `"gemini"`), then reads that provider's API key
134	    /// (`ANTHROPIC_API_KEY` / `GEMINI_API_KEY`, required) and model
135	    /// (`ANTHROPIC_MODEL` / `GEMINI_MODEL`, optional). Callers should run
136	    /// `dotenvy::dotenv().ok()` first if they want `.env` support -- see
137	    /// `.env.example`.
138	    pub fn from_env() -> Result<Self> {
139	        let provider = match env_var_nonempty("LLM_PROVIDER")
140	            .unwrap_or_else(|| "anthropic".to_string())
141	            .to_lowercase()
142	            .as_str()
143	        {
144	            "gemini" => Provider::Gemini,
145	            "anthropic" => Provider::Anthropic,
146	            other => bail!("unknown LLM_PROVIDER '{other}' (expected 'anthropic' or 'gemini')"),
147	        };
148	
149	        let (key_var, model_var, default_model) = match provider {
150	            Provider::Anthropic => (
151	                "ANTHROPIC_API_KEY",
152	                "ANTHROPIC_MODEL",
153	                DEFAULT_ANTHROPIC_MODEL,
154	            ),
155	            Provider::Gemini => ("GEMINI_API_KEY", "GEMINI_MODEL", DEFAULT_GEMINI_MODEL),
156	        };
157	        let api_key=[REDACTED] {
158	            format!("{key_var} is not set. Copy .env.example to .env and fill in a real key.")
159	        })?;
160	        let model = env_var_nonempty(model_var).unwrap_or_else(|| default_model.to_string());
161	
162	        Ok(Client {
163	            provider,
164	            api_key,
165	            model,
166	            http: reqwest::blocking::Client::new(),
167	        })
168	    }
169	
170	    pub fn send(
171	        &self,
172	        system: &str,
173	        messages: &[Message],
174	        tools: &[ToolDef],
175	    ) -> Result<ApiResponse> {
176	        match self.provider {
177	            Provider::Anthropic => self.send_anthropic(system, messages, tools),
178	            Provider::Gemini => self.send_gemini(system, messages, tools),
179	        }
180	    }
181	
182	    fn send_anthropic(
183	        &self,
184	        system: &str,
185	        messages: &[Message],
186	        tools: &[ToolDef],
187	    ) -> Result<ApiResponse> {
188	        let mut body = json!({
189	            "model": self.model,
190	            "max_tokens": MAX_TOKENS,
191	            "system": system,
192	            "messages": messages.iter().map(anthropic_message_to_json).collect::<Vec<_>>(),
193	        });
194	        if !tools.is_empty() {
195	            body["tools"] = Value::Array(tools.iter().map(anthropic_tool_to_json).collect());
196	        }
197	
198	        let raw = send_with_retries(
199	            || {
200	                self.http
201	                    .post(ANTHROPIC_API_URL)
202	                    .header("Content-Type", "application/json")
203	                    .header("x-api-key", &self.api_key)
204	                    .header("anthropic-version", ANTHROPIC_VERSION)
205	                    .json(&body)
206	            },
207	            "Anthropic",
208	        )?;
209	        parse_anthropic_response(&raw)
210	    }
211	
212	    fn send_gemini(
213	        &self,
214	        system: &str,
215	        messages: &[Message],
216	        tools: &[ToolDef],
217	    ) -> Result<ApiResponse> {
218	        let mut body = json!({
219	            "contents": messages_to_gemini_contents(messages),
220	            "systemInstruction": {"parts": [{"text": system}]},
221	        });
222	        if !tools.is_empty() {
223	            body["tools"] = json!([{
224	                "functionDeclarations": tools.iter().map(gemini_function_declaration).collect::<Vec<_>>(),
225	            }]);
226	        }
227	
228	        let url = format!(
229	            "https://generativelanguage.googleapis.com/v1beta/models/{}:generateContent?key={}",
230	            self.model, self.api_key
231	        );
232	        let raw = send_with_retries(
233	            || {
234	                self.http
235	                    .post(&url)
236	                    .header("Content-Type", "application/json")
237	                    .json(&body)
238	            },
239	            "Gemini",
240	        )?;
241	        parse_gemini_response(&raw)
242	    }
243	}
244	
245	const MAX_ATTEMPTS: u32 = 4;
246	
247	/// Sends a request built fresh by `build_request` on each attempt (a
248	/// `reqwest::RequestBuilder` is consumed by `.send()`, so it can't be
249	/// reused directly), retrying with exponential backoff (1s, 2s, 4s) on
250	/// transient failures: a network-level send error, HTTP 429, or a 5xx. A
251	/// non-retryable error (bad auth, malformed request, unexpected 4xx)
252	/// returns immediately instead of burning through retries pointlessly.
253	///
254	/// This exists because rapid back-to-back calls (e.g. the acceptance
255	/// harness running 5 strategies x 2 binaries) hit real, intermittent
256	/// failures against a live provider in practice -- see CHANGELOG for the
257	/// concrete numbers this was built in response to.
258	fn send_with_retries(
259	    build_request: impl Fn() -> reqwest::blocking::RequestBuilder,
260	    provider_label: &str,
261	) -> Result<Value> {
262	    let mut last_err: Option<anyhow::Error> = None;
263	    let mut wait = std::time::Duration::from_secs(1);
264	
265	    for attempt in 0..MAX_ATTEMPTS {
266	        if attempt > 0 {
267	            std::thread::sleep(wait);
268	        }
269	
270	        let resp = match build_request().send() {
271	            Ok(r) => r,
272	            Err(e) => {
273	                last_err = Some(
274	                    anyhow::Error::new(e)
275	                        .context(format!("sending request to the {provider_label} API")),
276	                );
277	                wait *= 2;
278	                continue;
279	            }
280	        };
281	
282	        let status = resp.status();
283	        // A 429's `Retry-After` header (standard) or, for Gemini, a
284	        // `retryDelay` field in the JSON error body, tells us exactly how
285	        // long the quota window needs -- a per-minute RPM cap needs tens of
286	        // seconds, far more than blind exponential backoff would wait
287	        // before giving up. Prefer that over guessing.
288	        let server_retry_after = retry_after_from_headers(resp.headers());
289	        let text = match resp.text() {
290	            Ok(t) => t,
291	            Err(e) => {
292	                last_err = Some(anyhow::Error::new(e).context("reading response body"));
293	                wait *= 2;
294	                continue;
295	            }
296	        };
297	
298	        if status.is_success() {
299	            return serde_json::from_str(&text)
300	                .with_context(|| format!("parsing {provider_label} API response body: {text}"));
301	        }
302	
303	        let body_desc = if text.is_empty() {
304	            "<empty body>"
305	        } else {
306	            &text
307	        };
308	        let err = anyhow::anyhow!("{provider_label} API returned {status}: {body_desc}");
309	        let retryable = status.as_u16() == 429 || status.is_server_error();
310	        if !retryable {
311	            return Err(err);
312	        }
313	        wait = server_retry_after
314	            .or_else(|| retry_delay_from_body(&text))
315	            .map(|secs| std::time::Duration::from_secs(secs + 1)) // +1s buffer
316	            .unwrap_or(wait * 2);
317	        last_err = Some(err);
318	    }
319	    Err(last_err.unwrap_or_else(|| {
320	        anyhow::anyhow!("{provider_label} API request failed with no captured error")
321	    }))
322	}
323	
324	fn retry_after_from_headers(headers: &reqwest::header::HeaderMap) -> Option<u64> {
325	    headers
326	        .get(reqwest::header::RETRY_AFTER)
327	        .and_then(|v| v.to_str().ok())
328	        .and_then(|s| s.parse::<u64>().ok())
329	}
330	
331	/// Best-effort search for Gemini's `"retryDelay": "22s"`-shaped field
332	/// anywhere in a JSON error body.
333	fn retry_delay_from_body(text: &str) -> Option<u64> {
334	    let value: Value = serde_json::from_str(text).ok()?;
335	    find_retry_delay(&value)
336	}
337	
338	fn find_retry_delay(value: &Value) -> Option<u64> {
339	    match value {
340	        Value::Object(map) => {
341	            if let Some(seconds) = map
342	                .get("retryDelay")
343	                .and_then(|v| v.as_str())
344	                .and_then(|s| s.strip_suffix('s'))
345	                .and_then(|n| n.parse::<u64>().ok())
346	            {
347	                return Some(seconds);
348	            }
349	            map.values().find_map(find_retry_delay)
350	        }
351	        Value::Array(arr) => arr.iter().find_map(find_retry_delay),
352	        _ => None,
353	    }
354	}
355	
356	// ---- Anthropic wire format ----
357	
358	fn anthropic_tool_to_json(tool: &ToolDef) -> Value {
359	    json!({
360	        "name": tool.name,
361	        "description": tool.description,
362	        "input_schema": tool.input_schema,
363	    })
364	}
365	
366	fn anthropic_message_to_json(message: &Message) -> Value {
367	    json!({
368	        "role": message.role,
369	        "content": message.content.iter().map(anthropic_content_block_to_json).collect::<Vec<_>>(),
370	    })
371	}
372	
373	fn anthropic_content_block_to_json(block: &ContentBlock) -> Value {
374	    match block {
375	        ContentBlock::Text { text } => json!({"type": "text", "text": text}),
376	        ContentBlock::ToolUse {
377	            id, name, input, ..
378	        } => {
379	            json!({"type": "tool_use", "id": id, "name": name, "input": input})
380	        }
381	        ContentBlock::ToolResult {
382	            tool_use_id,
383	            content,
384	        } => json!({"type": "tool_result", "tool_use_id": tool_use_id, "content": content}),
385	    }
386	}
387	
388	fn parse_anthropic_response(raw: &Value) -> Result<ApiResponse> {
389	    let content_arr = raw
390	        .get("content")
391	        .and_then(|c| c.as_array())
392	        .context("response missing `content` array")?;
393	
394	    let mut content = Vec::with_capacity(content_arr.len());
395	    for block in content_arr {
396	        let block_type = block.get("type").and_then(|t| t.as_str()).unwrap_or("");
397	        match block_type {
398	            "text" => content.push(ContentBlock::Text {
399	                text: block
400	                    .get("text")
401	                    .and_then(|t| t.as_str())
402	                    .unwrap_or_default()
403	                    .to_string(),
404	            }),
405	            "tool_use" => content.push(ContentBlock::ToolUse {
406	                id: block
407	                    .get("id")
408	                    .and_then(|v| v.as_str())
409	                    .unwrap_or_default()
410	                    .to_string(),
411	                name: block
412	                    .get("name")
413	                    .and_then(|v| v.as_str())
414	                    .unwrap_or_default()
415	                    .to_string(),
416	                input: block.get("input").cloned().unwrap_or(Value::Null),
417	                thought_signature: None,
418	            }),
419	            // "thinking" and other block types are intentionally ignored --
420	            // the trajectory log captures our own reasoning steps, not the
421	            // model's internal chain of thought.
422	            _ => {}
423	        }
424	    }
425	
426	    let stop_reason = raw
427	        .get("stop_reason")
428	        .and_then(|s| s.as_str())
429	        .unwrap_or("unknown")
430	        .to_string();
431	    let input_tokens = raw
432	        .get("usage")
433	        .and_then(|u| u.get("input_tokens"))
434	        .and_then(|v| v.as_u64())
435	        .unwrap_or(0) as u32;
436	    let output_tokens = raw
437	        .get("usage")
438	        .and_then(|u| u.get("output_tokens"))
439	        .and_then(|v| v.as_u64())
440	        .unwrap_or(0) as u32;
441	
442	    Ok(ApiResponse {
443	        content,
444	        stop_reason,
445	        input_tokens,
446	        output_tokens,
447	    })
448	}
449	
450	// ---- Gemini wire format ----
451	//
452	// Gemini's `contents`/`parts`/`role` shape uses "model" where Anthropic uses
453	// "assistant", has no id on a functionCall, and correlates a functionResponse
454	// back to its call by *name* rather than by id. Our internal `ContentBlock`
455	// keeps Anthropic's id-based shape (that's the format both binaries are
456	// written against), so translating out to Gemini means recovering each
457	// ToolResult's function name from the preceding ToolUse with the same id --
458	// done here with a simple linear scan, since a conversation is always small.
459	
460	fn gemini_function_declaration(tool: &ToolDef) -> Value {
461	    json!({
462	        "name": tool.name,
463	        "description": tool.description,
464	        "parameters": tool.input_schema,
465	    })
466	}
467	
468	fn messages_to_gemini_contents(messages: &[Message]) -> Vec<Value> {
469	    let mut id_to_name: std::collections::HashMap<&str, &str> = std::collections::HashMap::new();
470	    let mut contents = Vec::with_capacity(messages.len());
471	
472	    for message in messages {
473	        let role = if message.role == "assistant" {
474	            "model"
475	        } else {
476	            "user"
477	        };
478	        let mut parts = Vec::with_capacity(message.content.len());
479	        for block in &message.content {
480	            match block {
481	                ContentBlock::Text { text } => parts.push(json!({"text": text})),
482	                ContentBlock::ToolUse {
483	                    id,
484	                    name,
485	                    input,
486	                    thought_signature,
487	                } => {
488	                    id_to_name.insert(id.as_str(), name.as_str());
489	                    let mut part = json!({"functionCall": {"name": name, "args": input}});
490	                    // Gemini 3.x rejects a replayed functionCall part that's
491	                    // missing the signature it originally attached -- see
492	                    // the ContentBlock::ToolUse doc comment.
493	                    if let Some(sig) = thought_signature {
494	                        part["thoughtSignature"] = json!(sig);
495	                    }
496	                    parts.push(part);
497	                }
498	                ContentBlock::ToolResult {
499	                    tool_use_id,
500	                    content,
501	                } => {
502	                    let name = id_to_name
503	                        .get(tool_use_id.as_str())
504	                        .copied()
505	                        .unwrap_or("unknown_tool");
506	                    parts.push(json!({
507	                        "functionResponse": {
508	                            "name": name,
509	                            "response": {"result": content},
510	                        }
511	                    }));
512	                }
513	            }
514	        }
515	        contents.push(json!({"role": role, "parts": parts}));
516	    }
517	
518	    contents
519	}
520	
521	fn parse_gemini_response(raw: &Value) -> Result<ApiResponse> {
522	    let candidate = raw
523	        .get("candidates")
524	        .and_then(|c| c.as_array())
525	        .and_then(|arr| arr.first())
526	        .context("response missing `candidates[0]`")?;
527	
528	    let parts = candidate
529	        .get("content")
530	        .and_then(|c| c.get("parts"))
531	        .and_then(|p| p.as_array())
532	        .cloned()
533	        .unwrap_or_default();
534	
535	    let mut content = Vec::with_capacity(parts.len());
536	    for part in &parts {
537	        if let Some(text) = part.get("text").and_then(|t| t.as_str()) {
538	            content.push(ContentBlock::Text {
539	                text: text.to_string(),
540	            });
541	        } else if let Some(call) = part.get("functionCall") {
542	            let name = call
543	                .get("name")
544	                .and_then(|v| v.as_str())
545	                .unwrap_or_default()
546	                .to_string();
547	            // Newer Gemini models include a real call id; fall back to the
548	            // name (unique enough for our single-tool usage pattern) for
549	            // any that don't. Either way this doubles as the id used to
550	            // correlate the ToolResult sent back (see
551	            // `messages_to_gemini_contents`).
552	            let id = call
553	                .get("id")
554	                .and_then(|v| v.as_str())
555	                .map(|s| s.to_string())
556	                .unwrap_or_else(|| name.clone());
557	            // `thoughtSignature` is a sibling of `functionCall` on the Part
558	            // object, not nested inside it -- see ContentBlock::ToolUse.
559	            let thought_signature = part
560	                .get("thoughtSignature")
561	                .and_then(|v| v.as_str())
562	                .map(|s| s.to_string());
563	            content.push(ContentBlock::ToolUse {
564	                id,
565	                name,
566	                input: call.get("args").cloned().unwrap_or(Value::Null),
567	                thought_signature,
568	            });
569	        }
570	    }
571	
572	    let stop_reason = candidate
573	        .get("finishReason")
574	        .and_then(|s| s.as_str())
575	        .unwrap_or("unknown")
576	        .to_string();
577	    let input_tokens = raw
578	        .get("usageMetadata")
579	        .and_then(|u| u.get("promptTokenCount"))
580	        .and_then(|v| v.as_u64())
581	        .unwrap_or(0) as u32;
582	    let output_tokens = raw
583	        .get("usageMetadata")
584	        .and_then(|u| u.get("candidatesTokenCount"))
585	        .and_then(|v| v.as_u64())
586	        .unwrap_or(0) as u32;
587	
588	    Ok(ApiResponse {
589	        content,
590	        stop_reason,
591	        input_tokens,
592	        output_tokens,
593	    })
594	}
595	
596	#[cfg(test)]
597	mod tests {
598	    use super::*;
599	
600	    #[test]
601	    fn parses_an_anthropic_text_response() {
602	        let raw = json!({
603	            "content": [{"type": "text", "text": "hello"}],
604	            "stop_reason": "end_turn",
605	            "usage": {"input_tokens": 10, "output_tokens": 5}
606	        });
607	        let resp = parse_anthropic_response(&raw).unwrap();
608	        assert_eq!(resp.text(), "hello");
609	        assert_eq!(resp.stop_reason, "end_turn");
610	        assert_eq!(resp.input_tokens, 10);
611	        assert_eq!(resp.output_tokens, 5);
612	    }
613	
614	    #[test]
615	    fn parses_an_anthropic_tool_use_response() {
616	        let raw = json!({
617	            "content": [
618	                {"type": "text", "text": "Let me check."},
619	                {"type": "tool_use", "id": "toolu_1", "name": "shift_test", "input": {"strategy": "foo"}}
620	            ],
621	            "stop_reason": "tool_use",
622	            "usage": {"input_tokens": 20, "output_tokens": 8}
623	        });
624	        let resp = parse_anthropic_response(&raw).unwrap();
625	        let uses = resp.tool_uses();
626	        assert_eq!(uses.len(), 1);
627	        assert_eq!(uses[0].0, "toolu_1");
628	        assert_eq!(uses[0].1, "shift_test");
629	    }
630	
631	    #[test]
632	    fn parses_a_gemini_text_response() {
633	        let raw = json!({
634	            "candidates": [{
635	                "content": {"role": "model", "parts": [{"text": "hello"}]},
636	                "finishReason": "STOP"
637	            }],
638	            "usageMetadata": {"promptTokenCount": 12, "candidatesTokenCount": 6}
639	        });
640	        let resp = parse_gemini_response(&raw).unwrap();
641	        assert_eq!(resp.text(), "hello");
642	        assert_eq!(resp.input_tokens, 12);
643	        assert_eq!(resp.output_tokens, 6);
644	    }
645	
646	    #[test]
647	    fn parses_a_gemini_function_call_response() {
648	        let raw = json!({
649	            "candidates": [{
650	                "content": {"role": "model", "parts": [
651	                    {"functionCall": {"name": "shift_test", "args": {"hypothesis": "forward window"}}}
652	                ]},
653	                "finishReason": "STOP"
654	            }],
655	            "usageMetadata": {"promptTokenCount": 30, "candidatesTokenCount": 10}
656	        });
657	        let resp = parse_gemini_response(&raw).unwrap();
658	        let uses = resp.tool_uses();
659	        assert_eq!(uses.len(), 1);
660	        assert_eq!(uses[0].1, "shift_test");
661	    }
662	
663	    #[test]
664	    fn gemini_translation_recovers_function_name_for_tool_result() {
665	        let messages = vec![
666	            Message::user_text("hi"),
667	            Message {
668	                role: "assistant",
669	                content: vec![ContentBlock::ToolUse {
670	                    id: "shift_test".to_string(),
671	                    name: "shift_test".to_string(),
672	                    input: json!({}),
673	                    thought_signature: Some("sig123".to_string()),
674	                }],
675	            },
676	            Message {
677	                role: "user",
678	                content: vec![ContentBlock::ToolResult {
679	                    tool_use_id: "shift_test".to_string(),
680	                    content: "delta=0.1".to_string(),
681	                }],
682	            },
683	        ];
684	        let contents = messages_to_gemini_contents(&messages);
685	        assert_eq!(contents[1]["role"], "model");
686	        assert_eq!(contents[1]["parts"][0]["thoughtSignature"], "sig123");
687	        let function_response = &contents[2]["parts"][0]["functionResponse"];
688	        assert_eq!(function_response["name"], "shift_test");
689	        assert_eq!(function_response["response"]["result"], "delta=0.1");
690	    }
691	
692	    #[test]
693	    fn parses_thought_signature_from_a_gemini_function_call_part() {
694	        let raw = json!({
695	            "candidates": [{
696	                "content": {"role": "model", "parts": [
697	                    {"functionCall": {"name": "shift_test", "args": {}, "id": "call_1"}, "thoughtSignature": "abc"}
698	                ]},
699	                "finishReason": "STOP"
700	            }],
701	            "usageMetadata": {"promptTokenCount": 1, "candidatesTokenCount": 1}
702	        });
703	        let resp = parse_gemini_response(&raw).unwrap();
704	        match &resp.content[0] {
705	            ContentBlock::ToolUse {
706	                id,
707	                thought_signature,
708	                ..
709	            } => {
710	                assert_eq!(id, "call_1");
711	                assert_eq!(thought_signature.as_deref(), Some("abc"));
712	            }
713	            other => panic!("expected ToolUse, got {other:?}"),
714	        }
715	    }
716	}
